comms.text:
@1 וַהֲוָה כַּד שַׁלַח פַּרְעֹה יָת עַמָא וְלָא דַבָּרִינוּן יְיָ אֹרַח אַרְעָא פְלִשְׁתָּאֵי אֲרֵי קָרִיבָא הוּא אֲרֵי אֲמַר יְיָ דִילְמָא יְזוּעוּן עַמָא בְּמֶחֱזֵיהוֹן קְרָבָא וִיתוּבוּן לְמִצְרָיִם:
@2 וְאַסְחַר יְיָ יָת עַמָא אֹרַח מַדְבְּרָא יַמָא דְסוּף וּמְזָרְזִין סְלִיקוּ בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם:
@3 וְאַסִיק משֶׁה יָת גַרְמֵי יוֹסֵף עִמֵהּ אֲרֵי אוֹמָאָה אוֹמִי יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר מִדְכַּר דְכִיר יְיָ יָתְכוֹן וְתַסְקוּן יָת גַרְמַי מִכָּא עִמְכוֹן:
@4 וּנְטָלוּ מִסֻכּוֹת וּשְׁרוֹ בְאֵתָם בִּסְטַר מַדְבְּרָא:
@5 וַיְיָ מְדַבַּר קָדָמֵיהוֹן בִּימָמָא בְּעַמוּדָא דַעֲנָנָא לְדַבָּרוּתְהוֹן בְּאוֹרְחָא וְלֵילְיָא בְּעַמוּדָא דְאֶשָׁתָא לְאַנְהָרָא לְהוֹן לְמֵיזַל בִּימָמָא וּבְלֵילְיָא:
@6 לָא יַעֲדֵי עַמוּדָא דַעֲנָנָא בִּימָמָא וְאַף לָא עַמוּדָא דְאֶשָׁתָא בְּלֵילְיָא קֳדָם עַמָא:
@7 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@8 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וִיתוּבּוּן וְיִשְׁרוּן קֳדָם פּוּם חִירָתָא בֵּין מִגְדוֹל וּבֵין יַמָא קֳדָם בְּעֵיל צְפוֹן לְקִבְלֵהּ תִּשְׁרוּן עַל יַמָא:
@9 וְיֵימַר פַּרְעֹה עַל בְּנֵי יִשְׂרָאֵל מְעַרְבְּלִין אִנוּן בְּאַרְעָא אֲחַד עֲלֵיהוֹן מַדְבְּרָא:
@10 וְאַתְקֵף יָת לִבָּא דְפַרְעֹה וְיִרְדַף בַּתְרֵיהוֹן וְאֶתְיַקַר בְּפַרְעֹה וּבְכָל מַשִׁרְיָתֵהּ וְיִדְעוּן מִצְרָאֵי אֲרֵי אֲנָא יְיָ וַעֲבָדוּ כֵן:
@11 וְאִתְחַוָא לְמַלְכָּא דְמִצְרַיִם אֲרֵי אֲזַל עַמָא וְאִתְהֲפִיךְ לִבָּא דְפַרְעֹה וְעַבְדוֹהִי לְעַמָא וַאֲמָרוּ מָא דָא עֲבַדְנָא אֲרֵי שַׁלַחְנָא יָת יִשְׂרָאֵל מִפָּלְחָנָנָא:
@12 וְטַקִיס יָת רְתִכֵּהּ וְיָת עַמֵהּ דַבַּר עִמֵהּ:
@13 וּדְבַר שִׁתְּ מְאָה רְתִכִּין בְּחִירָן וְכֹל רְתִכֵּי מִצְרָאֵי וְגִבָּרִין מְמַנָן עַל כֻּלְהוֹן:
@14 וְתַקִיף יְיָ יָת לִבָּא דְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּרְדַף בָּתַר בְּנֵי יִשְׂרָאֵל וּבְנֵי יִשְׂרָאֵל נְפָקוּ בְּרֵישׁ גְלִי:
@15 וּרְדָפוּ מִצְרָאֵי בַּתְרֵיהוֹן וְאַדְבִּיקוּ יָתְהוֹן כַּד שָׁרָן עַל יַמָא כָּל סוּסָוַת רְתִכֵּי פַרְעֹה וּפָרָשׁוֹהִי וּמַשִׁרְיָתֵהּ עַל פּוּם חִירָתָא קֳדָם בְּעֵיל צְפוֹן:
@16 וּפַרְעֹה קְרֵיב וּזְקָפוּ בְנֵי יִשְׂרָאֵל יָת עֵינֵיהוֹן וְהָא מִצְרָאֵי נַטְלִין בַּתְרֵיהוֹן וּדְחִילוּ לַחֲדָא וּזְעִיקוּ בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ:
@17 וַאֲמָרוּ לְמשֶׁה הֲמִדְלֵית קְבָרִין בְּמִצְרַיִם דְבַרְתָּנָא לִמְמַת בְּמַדְבְּרָא מָא דָא עֲבַדְתָּא לָנָא לְאַפָּקוּתָנָא מִמִצְרָיִם:
@18 הֲלָא דֵין פִּתְגָמָא דִי מַלֵלְנָא עִמָךְ בְמִצְרַיִם לְמֵימַר שְׁבוֹק מִנָנָא וְנִפְלַח יָת מִצְרָאֵי אֲרֵי טַב לָנָא דְנִפְלַח יָת מִצְרָאֵי מִדִנְמוּת בְּמַדְבְּרָא:
@19 וַאֲמַר משֶׁה לְעַמָא לָא תִדְחֲלוּן אִתְעַתָּדוּ וַחֲזוֹ יָת פּוּרְקָנָא דַיְיָ דְיַעְבֵּד לְכוֹן יוֹמָא דֵין אֲרֵי כְּמָא דִחֲזֵיתוּן יַת מִצְרָאֵי יוֹמָא דֵין לָא תוֹסְפוּן לְמֶחֱזֵיהוֹן עוֹד עַד עָלְמָא:
@20 יְיָ יְגִיחַ לְכוֹן קְרָב וְאַתּוּן תִּשְׁתְּקוּן:
@21 וַאֲמַר יְיָ לְמשֶׁה קַבֵּלִית צְלוֹתָךְ מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְיִטְלוּן:
@22 וְאַתְּ טוֹל יָת חֻטְרָךְ וַאֲרֵים יָת יְדָךְ עַל יַמָא וּבְזָעוֹהִי וְיֵעֲלוּן בְּנֵי יִשְׂרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא:
@23 וַאֲנָא הָא אֲנָא מְתַקֵף יָת לִבָּא דְמִצְרָאֵי וְיֵעֲלוּן בַּתְרֵיהוֹן וְאֶתְיַקַר בְּפַרְעֹה וּבְכָל מַשִׁרְיָתֵהּ בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי:
@24 וְיִדְּעוּן מִצְרָאֵי אֲרֵי אֲנָא יְיָ בְּאִתְיַקָרוּתִי בְּפַרְעֹה בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי:
@25 וּנְטַל מַלְאֲכָא דַיְיָ דִמְדַבַּר קֳדָם מַשְׁרִיתָא דְיִשְׂרָאֵל וַאֲתָא מִבַּתְרֵיהוֹן וּנְטַל עַמּוּדָא דַעֲנָנָא מִן קֳדָמֵיהוֹן וּשְׁרָא מִבַּתְרֵיהוֹן:
@26 וְעַל בֵּין מַשְׁרִיתָא דְמִצְרָאֵי וּבֵין מַשְׁרִיתָא דְיִשְׂרָאֵל וַהֲוָה עֲנָנָא וְקַבְלָא לְמִצְרָאֵי וּלְיִשְׂרָאֵל נְהַר כָּל לֵילְיָא וְלָא אִתְקְרִיבוּ דֵין לְוָת דֵין כָּל לֵילְיָא:
@27 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל יַמָּא וְדַבַּר יְיָ יָת יַמָּא בְּרוּחַ קִדוּמָא תַקִיף כָּל לֵילְיָא וְשַׁוִי יָת יַמָּא לְיַבֶּשְׁתָּא וְאִתְבְּזָעוּ מַיָּא:
@28 וְעַלוּ בְנֵי יִשְׂרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא וּמַיָּא לְהוֹן שׁוּרִין מִיַּמִינֵהוֹן וּמִסְמָאלֵהוֹן:
@29 וּרְדָפוּ מִצְרָאֵי וְעַלוּ בַתְרֵיהוֹן כֹּל סוּסָוַת פַּרְעֹה רְתִכּוֹהִי וּפָרָשׁוֹהִי לְגוֹ יַמָא:
@30 וַהֲוָה בְּמַטְרַת צַפְרָא וְאִסְתְּכֵי יְיָ לְמַשְׁרִיתָא דְמִצְרָאֵי בְּעַמוּדָא דְאֶשָׁתָא וַעֲנָנָא וְשַׁגִישׁ יָת מַשְׁרִיתָא דְמִצְרָאֵי:
@31 וְאַעְדִי יָת גַלְגַלֵי רְתִכּוֹהִי וּמְדַבְּרִין לְהוֹן בִּתְקוֹף וַאֲמַר מִצְרָאֵי נֵעִירוֹק מִן קֳדָם יִשְׂרָאֵל אֲרֵי דָא הִיא גְבֻרְתָּא דַיְיָ דַעֲבֵד לְהוֹן קְרָבִין בְּמִצְרָיִם:
@32 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יָת יְדָךְ עַל יַמָא וִיתוּבוּן מַיָא עַל מִצְרָאֵי עַל רְתִכֵּיהוֹן וְעַל פָּרָשֵׁיהוֹן:
@33 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל יַמָא וְתָב יַמָא לְעִדַן צַפְרָא לְתָקְפֵּהּ וּמִצְרָאֵי עָרְקִין לְקַדָמוּתֵהּ וְשַׁנִיק יְיָ יָת מִצְרָאֵי בְּגוֹ יַמָא:
@34 וְתָבוּ מַיָא וַחֲפוֹ יָת רְתִכַּיָא וְיָת פָּרָשַׁיָא לְכֹל מַשִׁרְיַת פַּרְעֹה דְעַלוּ בַתְרֵיהוֹן בְּיַמָא לָא אִשְׁתָּאַר בְּהוֹן עַד חָד:
@35 וּבְנֵי יִשְׂרָאֵל הַלִיכוּ בְיַבֶּשְׁתָּא בְּגוֹ יַמָא וּמַיָא לְהוֹן שׁוּרִין מִיַמִינֵהוֹן וּמִסְמָאלֵהוֹן:
@36 וּפְרַק יְיָ בְּיוֹמָא הַהוּא יָת יִשְׂרָאֵל מִידָא דְמִצְרָאֵי וַחֲזוֹ יִשְׂרָאֵל יָת מִצְרָאֵי מַיְתִין עַל כֵּיף יַמָא:
@37 וַחֲזָא יִשְׂרָאֵל יָת גְבוּרְתָּא יְדָא רַבְּתָא דִי עֲבַד יְיָ בְּמִצְרַיִם וּדְחִילוּ עַמָא מִן קֳדָם יְיָ וְהֵמִינוּ בְּמֵימְרָא דַיְיָ וּבִנְבִיאוּת משֶׁה עַבְדֵהּ:
@38 בְּכֵן שַׁבַּח משֶׁה וּבְנֵי יִשְׂרָאֵל יָת תִּשְׁבַּחְתָּא הָדָא קֳדָם יְיָ וַאֲמָרוּ לְמֵימָר נְשַׁבַּח וְנוֹדֶה קָדָם יְיָ אֲרֵי אִתְגָאֵי עַל גֵוְתָנַיָא וְגֵאוּתָא דִילֵהּ הִיא סוּסְיָא וְרָכְבֵהּ רְמָא בְיַמָא:
@39 תָּקְפִּי וְתִשְׁבַּחְתִּי דְחִילָא יְיָ וַאֲמַר בְּמֵימְרֵהּ וַהֲוָה לִי לְפָרָק דֵין אֱלָהַי וְאֶבְנֵי לֵהּ מַקְדְשָׁא אֱלָהָא דַאֲבָהָתַי וְאֶפְלַח קֳדָמוֹהִי:
@40 יְיָ מָרֵי נִצְחָן קְרָבַיָא יְיָ שְׁמֵהּ:
@41 רְתִכֵּי פַּרְעֹה וּמַשִׁרְיָתֵהּ שְׁדִי בְיַמָא וּשְׁפַר גִבָּרוֹהִי אִטְבָּעוּ בְּיַמָא דְסוּף:
@42 תְּהוֹמַיָא חֲפוֹ עֲלֵיהוֹן נְחָתוּ לְעוּמְקַיָא כְּאַבְנָא:
@43 יַמִינָךְ יְיָ אַדִיר בְּחֵילָא יַמִינָךְ יְיָ תְּבָּרַת סָנְאָה:
@44 וּבִסְגֵי תָקְפָּךְ תְּבַרְתָּנוּן לִדְקָמוּ עַל עַמָךְ שַׁלַחְתָּ רוּגְזָךְ שֵׁיצִנוּן כְּנוּרָא לְקַשָׁא:
@45 וּבְמֵימַר פּוּמָךְ חַכִּימוּ מַיָא קָמוּ כְשׁוּר אֲזָלַיָא קָפוּ תְהוֹמִין בְּלִבָּא דְיַמָא:
@46 דַהֲוָה אֲמַר סָנְאָה אֶרְדוֹף אַדְבֵּק אֲפַלֵג בִּזְתָא תִּשְׂבַּע מִנְהוֹן נַפְשִׁי אֶשְׁלוֹף חַרְבִּי תְּשֵׁיצִינוּן יְדִי:
@47 אֲמַרְתָּ בְּמֵימְרָךְ חֲפָא עֲלֵיהוֹן יַמָא אִשְׁתְּקָעוּ כַּאֲבָרָא בְּמַיִן תַּקִיפִין:
@48 לֵית בַּר מִנָךְ דְאַתְּ הוּא אֱלָהָא יְיָ לֵית בַּר מִנָךְ אֱלָהָא אַתְּ אַדִיר בְּקוּדְשָׁא דָחֵל תֻּשְׁבְּחָן עָבֵד פָּרִישָׁן:
@49 אֲרֵמְתָּ יַמִינָךְ בְּלַעְתְּנוּן אַרְעָא:
@50 דַבַּרְהִי בְטַבְוָתָךְ עַמָא דְנַן דִפְרָקְתָּ סוֹבַרְהִי בְתָקְפָּךְ לְדִירָא דְקֻדְשָׁךְ:
@51 שְׁמָעוּ עַמְמַיָא וְזָעוּ דַחֲלָא אַחֲדָתְנוּן דַהֲווֹ יָתְבִין בִּפְלָשֶׁת:
@52 בְּכֵן אִתְבְּהִילוּ רַבְרְבֵי אֱדוֹם תַּקִיפֵי מוֹאָב אֲחַדָתְנוּן רְתֵיתָא אִתְבָּרוּ כֹּל דַהֲווֹ יָתְבִין בִּכְנָעַן:
@53 תַּפִּיל עֲלֵיהוֹן אֵימְתָא וְדַחַלְתָּא בִּסְגֵי תָקְפָּךְ יִשְׁתְּקוּן כְּאַבְנָא עַד דְיֵעִבַּר עַמָךְ יְיָ יָת אַרְנוֹנָא עַד דְיֵעִבַּר עַמָא דְנַן דִי פְרַקְתָּא יָת יַרְדְנָא:
@54 תָּעֵלִנוּן וְתַשְׁרִינוּן בְּטוּרָא דְאַחְסַנְתָּךְ אֲתַר מְתַקֵן לְבֵית שְׁכִנְתָּךְ אַתְקֵנְתָּא יְיָ מַקְדְשָׁא יְיָ אַתְקְנוֹהִי יְדָיךְ:
@55 יְיָ מַלְכוּתֵהּ קָאֵם לְעָלַם וּלְעָלְמֵי עָלְמַיָא:
@56 אֲרֵי עַלוּ סוּסָוַת פַּרְעֹה בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי בְּיַמָא וַאֲתֵיב יְיָ עֲלֵיהוֹן יָת מֵי יַמָא וּבְנֵי יִשְׂרָאֵל הַלִיכוּ בְיַבֶּשְׁתָּא בְּגוֹ יַמָא:
@57 וּנְסֵיבַת מִרְיָם נְבִיאֲתָא אֲחָתֵהּ דְאַהֲרֹן יָת תֻּפָּא בִּידַהּ וּנְפָקוּ כָל נְשַׁיָא בַּתְרָהָא בְּתֻפִּין וּבְחִנְגִין:
@58 וּמְעַנְיָא לְהוֹן מִרְיָם שַׁבָּחוּ וְאוֹדוּ קֳדָם יְיָ אֲרֵי אִתְגָאֵי עַל גֵוְתָנַיָא וְגֵאוּתָא דִילֵהּ הִיא סוּסְיָא וְרָכְבֵהּ רְמָא בְיַמָא:
@59 וְאַטֵּל משֶׁה יָת יִשְׂרָאֵל מִיַמָא דְסוּף וּנְפָקוּ לְמַדְבְּרָא דְחַגְרָא וַאֲזָלוּ תְלָתָא יוֹמִין בְּמַדְבְּרָא וְלָא אַשְׁכָּחוּ מַיָא:
@60 וַאֲתוֹ לְמָרָה וְלָא יְכִילוּ לְמִשְׁתֵּי מַיָא מִמָרָה אֲרֵי מְרִירִין אִנוּן עַל כֵּן קְרָא שְׁמַהּ מָרָה:
@61 וְאִתְרָעָמוּ עַמָא עַל משֶׁה לְמֵימַר מָה נִשְׁתֵּי:
@62 וְצַלִי קֳדָם יְיָ וְאַלְפֵהּ יְיָ אָעָא וּרְמָא לְמַיָא וּבַסִימוּ מַיָא תַּמָן גְזַר לֵהּ קְיָם וְדִין וְתַמָן נַסְיֵהּ:
@63 וַאֲמַר אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וּדְכָשַׁר קֳדָמוֹהִי תַעְבֵּד וְתַצֵית לִפִקוּדוֹהִי וְתִטַר כָּל קְיָמוֹהִי כָּל מַרְעִין דִי שַׁוֵיתִי בְמִצְרַיִם לָא אֲשַׁוִנוּן עֲלָךְ אֲרֵי אֲנָא יְיָ אַסָךְ:
@64 וַאֲתוֹ לְאֵילִם וְתַמָן תְּרֵי עֲסַר מַבּוּעִין דְמַיִן וְשִׁבְעִין דִקְלִין וּשְׁרוֹ תַמָן עַל מַיָא:
@65 וּנְטָלוּ מֵאֵילִם וַאֲתוֹ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְּמַדְבְּרָא דְסִין דִי בֵין אֵילִם וּבֵין סִינָי בְּחַמְשַׁת עַסְרָא יוֹמָא לְיַרְחָא תִנְיָנָא לְמִפָּקְהוֹן מֵאַרְעָא דְמִצְרַיִם:
@66 וְאִתְרָעָמוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל עַל משֶׁה וְעַל אַהֲרֹן בְּמַדְבְּרָא:
@67 וַאֲמָרוּ לְהוֹן בְּנֵי יִשְׂרָאֵל לְוַי דְמִיתְנָא קֳדָם יְיָ בְּאַרְעָא דְמִצְרַיִם כַּד הֲוֵינָא יָתְבִין עַל דוּדֵי בִסְרָא כַּד הֲוֵינָא אָכְלִין לַחְמָא וְשָׂבְעִין אֲרֵי אַפֶּקְתּוּן יָתָנָא לְמַדְבְּרָא הָדֵין לְקַטָּלָא יָת כָּל קְהָלָא הָדֵין בְּכַפְנָא:
@68 וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מָחֵית לְכוֹן לַחְמָא מִן שְׁמַיָא וְיִפְקוּן עַמָא וְיִלְקְטוּן פִּתְגַם יוֹם בְּיוֹמֵהּ בְּדִיל דַאֲנַסִנוּן הַיְהָכוּן בְּאוֹרַיְתִי אִם לָא:
@69 וִיהֵי בְּיוֹמָא שְׁתִיתָאָה וִיתַקְנוּן יָת דְיַיְתוּן וִיהֵי עַל חַד תְּרֵין עַל דְיִלְקְטוּן יוֹם יוֹם:
@70 וַאֲמַר משֶׁה וְאַהֲרֹן לְכָל בְּנֵי יִשְׂרָאֵל בְּרַמְשָׁא וְתִדְעוּן אֲרֵי יְיָ אַפֵּיק יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@71 וּבְצַפְרָא וְתֶחֱזוּן יָת יְקָרָא דַיְיָ כַּד שְׁמִיעַ (קֳדָמוֹהִי) יָת תֻּרְעֲמוּתְכוֹן עַל מֵימְרָא דַיְיָ וְנַחְנָא מָא אֲרֵי אַתְרַעַמְתּוּן עֲלָנָא:
@72 וַאֲמַר משֶׁה בִּדְיִתֵּן יְיָ לְכוֹן בְּרַמְשָׁא בִּסְרָא לְמֵיכַל וְלַחְמָא בְּצַפְרָא לְמִסְבַּע בְּדִשְׁמִיעַן קֳדָם יְיָ יָת תֻּרְעֲמוּתְכוֹן דִי אַתּוּן מִתְרַעֲמִין עֲלוֹהִי וְנַחְנָא מָא לָא עֲלָנָא תֻּרְעֲמוּתְכוֹן אֶלָהֵן עַל מֵימְרָא דַיְיָ:
@73 וַאֲמַר משֶׁה לְאַהֲרֹן אֱמַר לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל קְרִיבוּ קֳדָם יְיָ אֲרֵי שְׁמִיעַן קֳדָמוֹהִי יָת תֻּרְעֲמוּתְכוֹן:
@74 וַהֲוָה כַּד מַלִיל אַהֲרֹן עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵלּ וְאִתְפְּנִיוּ לְמַדְבְּרָא וְהָא יְקָרָא דַיְיָ אִתְגְלִי בַּעֲנָנָא:
@75 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@76 שְׁמִיעַ קֳדָמַי יָת תֻּרְעֲמַת בְּנֵי יִשְּׂרָאֵל מַלֵיל עִמְהוֹן לְמֵימַר בֵּין שִׁמְשַׁיָא תֵּיכְלּוּן בִּסְרָא וּבְצַפְרָא תִּשְׂבְּעוּן לַחְמָא וְתִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@77 וַהֲוָה בְרַמְשָׁא וּסְלֵיקַת סְלָיו וַחֲפַת יָת מַשְׁרִיתָא וּבְצַפְרָא הֲוַת נְחָתַת טַלָא סְחוֹר סְחוֹר לְמַשְׁרִיתָא:
@78 וּסְלֵיקַת נְחָתַת טַלָא וְהָא עַל אַפֵּי מַדְבְּרָא דַעְדַק מְקַלַף דַעְדַק כְּגִיר כִּגְלִידָא עַל אַרְעָא:
@79 וַחֲזוֹ בְנֵי יִשְׂרָאֵל וַאֲמָרוּ גְבַר לַאֲחוּהִי מַנָא הוּא אֲרֵי לָא יְדָעוּ מָא הוּא וַאֲמַר משֶׁה לְהוֹן הוּא לַחְמָא דִי יְהַב יְיָ לְכוֹן לְמֵיכַל:
@80 דֵין פִּתְגָמָא דִי פַקֵיד יְיָ לְקוּטוּ מִנֵהּ גְבַר לְפוּם מֵיכְלֵהּ עֻמְרָא לְגֻלְגַלְתָּא מִנְיַן נַפְשָׁתֵיכוֹן גְבַר לְדִי בְמַשְׁכְּנֵהּ תִּסְבוּן:
@81 וַעַבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וּלְקָטוּ דְאַסְגֵי וּדְאַזְעֵר:
@82 וּכְלוֹ בְעוּמְרָא וְלָא אוֹתַר דְאַסְגֵי וּדְאַזְעֵר לָא חַסִיר גְבַר לְפוּם מֵיכְלֵהּ לְקָטוּ:
@83 וַאֲמַר משֶׁה לְהוֹן אֱנַשׁ לָא יַשְׁאַר מִנֵהּ עַד צַפְרָא:
@84 וְלָא קַבִּילוּ מִן משֶׁה וְאַשְׁאָרוּ גֻבְרַיָא מִנֵה עַד צַפְרָא וּרְחֵשׁ רִיחֲשָׁא וּסְרִי וּרְגַז עֲלֵיהוֹן משֶׁה:
@85 וּלְקָטוּ יָתֵהּ בִּצְפַר בִּצְפָר גְבַר לְפוּם מֵיכְלֵהּ וּמָא דְמִשְׁתָּאַר מִנֵהּ עַל אַפֵּי חַקְלָא כַּד חֲמָא עֲלוֹהִי שִׁמְשָׁא פָּשָׁר:
@86 וַהֲוָה בְּיוֹמָא שְׁתִיתָאָה לְקָטוּ לַחְמָא עַל חַד תְּרֵין תְּרֵין עֻמְרִין לְחָד וַאֲתוֹ כָּל רַבְרְבֵי כְנִשְׁתָּא וְחַוִיאוּ לְמשֶׁה:
@87 וַאֲמַר לְהוֹן הוּא דִי מַלִיל יְיָ שְׁבָתָא שְׁבַת קוּדְשָׁא קֳדָם יְיָ מְחָר יָת דִי אַתּוּן עֲתִידִין לְמֵפָא אֲפוֹ וְיָת דִי אַתּוּן עֲתִידִין לְבַשָׁלָא בַּשִׁילוּ וְיָת כָּל מוֹתָרָא אַצְנָעוּ לְכוֹן לְמַטְּרַת עַד צַפְרָא:
@88 וְאַצְנָעוּ יָתֵהּ עַד צַפְרָא כְּמָא דְפַקִיד משֶׁה וְלָא סְרִי וְרִיחֲשָׁא לָא הֲוָה בֵהּ:
@89 וַאֲמַר משֶׁה אִכְלוּהִי יוֹמָא דֵין אֲרֵי שַׁבְּתָא יוֹמָא דֵין קֳדָם יְיָ יוֹמָא דֵין לָא תַשְׁכְּחֻנֵהּ בְּחַקְלָא:
@90 שִׁתָּא יוֹמִין תִּלְקְטֻנֵהּ וּבְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא לָא יְהֵי בֵהּ:
@91 וַהֲוָה בְּיוֹמָא שְׁבִיעָאָה נְפָקוּ מִן עַמָא לְמִלְקָטּ וְלָא אַשְׁכָּחוּ:
@92 וַאֲמַר יְיָ לְמשֶׁה עַד אֵימָתַי אַתּוּן מְסָרְבִין לְמִטַר פִּקוּדַי וְאוֹרָיָתַי:
@93 חֲזוֹ אֲרֵי יְיָ יְהַב לְכוֹן שַׁבְּתָא עַל כֵּן הוּא יָהֵב לְכוֹן בְּיוֹמָא שְׁתִיתָאָה לְחֵם תְּרֵין יוֹמִין תִּיבוּ אֲנַשׁ תְּחוֹתוֹהִי לָא יִפּוֹק אֲנַשׁ מֵאַתְרֵהּ בְּיוֹמָא שְׁבִיעָאָה:
@94 וְנָחוּ עַמָא בְּיוֹמָא שְׁבִיעָאָה:
@95 וּקְרוֹ בֵית יִשְׂרָאֵל יָת שְׁמֵהּ מָן וְהוּא כְּבַר זְרַע גִדָא חִוָר וְטַעְמֵה כְּאִסְקְרֵיטָוָן בִּדְבָשׁ:
@96 וַאֲמַר משֶׁה דֵין פִּתְגָמָא דִי פַקִיד יְיָ מִלֵי עֻמְרָא מִנֵהּ לְמַטְרָא לְדָרֵיכוֹן בְּדִיל דְיֶחְזוּן יָת לַחְמָא דִי אוֹכָלִית יָתְכוֹן בְּמַדְבְּרָא בְּאַפָּקוּתִי יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@97 וַאֲמַר משֶׁה לְאַהֲרֹן סַב צְלוֹחִית חֲדָא וְהַב תַמָן מְלֵי עֻמְרָא מָן וְאַצְנַע יָתֵהּ קֳדָם יְיָ לְמַטְרָא לְדָרֵיכוֹן:
@98 כְּמָא דִי פַקִיד יְיָ לְמשֶׁה וְאַצְנְעֵהּ אַהֲרֹן קֳדָם סַהֲדוּתָא לְמַטְרָא:
@99 וּבְנֵי יִשְׂרָאֵל אֲכָלוּ יָת מַנָא אַרְבְּעִין שְׁנִין עַד דְמֵיתֵיהוֹן לְאַרְעָא יָתְבָתָא יָת מַנָא אֲכָלוּ עַד דְאָתוֹ לִסְיָפֵי אַרְעָא דִכְנָעַן:
@100 וְעֻמְרָא חַד מִן עַסְרָא בִּתְלָת סְאִין הוּא:
@101 וּנְטָלוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִמַדְבְּרָא דְסִין לְמַטְלָנֵיהוֹן עַל מֵימְרָא דַיְיָ וּשְׁרוֹ בִּרְפִידִים וְלֵית מַיָא לְמִשְׁתֵּי עַמָא:
@102 וּנְצָא עַמָא עִם משֶׁה וַאֲמָרוּ הָבוּ לָנָא מַיָא וְנִשְׁתֵּי וַאֲמַר לְהוֹן משֶׁה מָא אַתּוּן נָצָן עִמִי מָא מְנַסוּן אַתּוּן קֳדָם יְיָ:
@103 וּצְחִי תַמָן עַמָא לְמַיָא וְאִתְרַעַם עַמָא עַל משֶׁה וַאֲמַר לְמָא דְנַן אַסֶקְתָּנָא מִמִצְרַיִם לְקַטָלָא יָתִי וְיָת בָּנַי וְיָת בְּעִירַי בְּצָחוּתָא:
@104 וְצַלִי משֶׁה קֳדָם יְיָ לְמֵימַר מָא אֶעְבֵּד לְעַמָא הָדֵין עוֹד זְעֵיר פּוֹן וְיִרְגְמֻנִי:
@105 וַאֲמַר יְיָ לְמשֶׁה עִבַּר קֳדָם עַמָא וּדְבַר עִמָךְ מִסָבֵי יִשְׂרָאֵל וְחֻטְרָךְ דִי מָחֵיתָא בֵהּ יָת נַהֲרָא סַב בִּידָךְ וְתֵיזִל:
@106 הָא אֲנָא קָאֵם קֳדָמָךְ תַּמָן עַל טִנָרָא בְּחוֹרֵב וְתִמְחֵי בְטִנָרָא וְיִפְּקוּן מִנֵהּ מַיָא וְיִשְׁתֵּי עַמָא וַעֲבַד כֵּן משֶׁה לְעֵינֵי סָבֵי יִשְׂרָאֵל:
@107 וּקְרָא שְׁמָא דְאַתְרָא נִסֵיתָא וּמַצוּתָא עַל דִנְצוֹ בְּנֵי יִשְׂרָאֵל וְעַל דְנַסִיאוּ קֳדָם יְיָ לְמֵימַר הֲאִית שְׁכִינְתָּא דַיְיָ בֵּינָנָא אִם לָא:
@108 וַאֲתָא עֲמָלֵק וַאֲגַח קְרָבָא עִם יִשְׂרָאֵל בִּרְפִידִם:
@109 וַאֲמַר משֶׁה לִיהוֹשֻׁעַ בְּחַר לָנָא גֻבְרַיָא וּפוּק אֲגַח קְרָבָא בַּעֲמָלֵק מְחָר אֲנָא קָאֵם עַל רֵישׁ רָמָתָא וְחוּטְרָא דְאִתְעֲבִידוּ בֵהּ נִסִין מִן קֳדָם יְיָ בִּידִי:
@110 וַעֲבַד יְהוֹשֻׁעַ כְּמָא דְאֲמַר לֵהּ משֶׁה לְאַגָחָא קְרָבָא בַּעֲמָלֵק וּמשֶׁה אַהֲרֹן וְחוּר סְלִיקוּ לְרֵישׁ רָמָתָא:
@111 וַהֲוִי כַּד יְרִים משֶׁה יְדוֹהִי וּמִתְגַבְּרִין דְבֵית יִשְׂרָאֵל וְכַד מַנַח יְדוֹהִי וּמִתְגַבְּרִין דְבֵית עֲמָלֵק:
@112 וִידֵי משֶׁה יְקָרָן וּנְסִיבוּ אַבְנָא וְשַׁוִיאוּ תְחוֹתוֹהִי וִיתֵב עֲלַהּ וְאַהֲרֹן וְחוּר סַעְדָן בִּידוֹהִי מִכָּא חַד וּמִכָּא חַד וַהֲוָה יְדוֹהִי פְּרִיסָן בִּצְלוֹ עַד דְעַל שִׁמְשָׁא:
@113 וְתַבַּר יְהוֹשֻׁעַ יָת עֲמָלֵק וְיָת עַמֵהּ לְפִתְגָם דְחָרֶב:
@114 וַאֲמַר יְיָ לְמשֶׁה כְּתָב דָא דוּכְרָנָא בְּסִפְרָא וְשַׁוִי קֳדָם יְהוֹשֻׁעַ אֲרֵי מִמְחָא אֶמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא:
@115 וּבְנָא משֶׁה מַדְבְּחָא וּפְלַח עֲלוֹהִי קֳדָם יְיָ דַעֲבַד לֵהּ נִסִין:
@116 וַאֲמַר בִּשְׁבוּעָה אֲמִירָא דָא מִן קֳדָם דְחֵילָא דִשְׁכִנְתֵּהּ עַל כָּרְסֵהּ יְקָרֵהּ דְעָתִיד דְאִתָּגַח קְרָבָא קֳדָם יְיָ בִּדְבֵית עֲמָּלֵק לְשֵׁצָיוּתְהוֹן מִדָרֵי עָלְמָא: פפפ:

@1 **ויהי בשלח פרעה** וגו' **ולא נחם.** ולא נהגם, כמו (שמות לב לד) לך נחה את העם, (משלי ו כב) בהתהלכך תנחה אותך: **כי קרוב הוא.** ונוח לשוב באותו הדרך למצרים. ומדרשי אגדה יש הרבה: **בראתם מלחמה.** כגון מלחמת (במדבר יד מה) וירד העמלקי והכנעני וגו' . אם הלכו דרך ישר היו חוזרים, ומה אם כשהקיפם דרך מעקם אמרו (במדבר יד ד) נתנה ראש ונשובה מצרימה, אם הוליכם בפשוטה על אחת כמה וכמה: **פן ינחם.** יחשבו מחשבה על שיצאו ויתנו לב לשוב:
@2 **ויסב.** הסבם מן הדרך הפשוטה לדרך העקומה: **ים סוף.** כמו לים סוף. וסוף הוא לשון אגם שגדלים בו קנים, כמו (שמות ב ג) ותשם בסוף, (ישעיה יט ו) קנה וסוף קמלו: **וחמשים.** אין חמושים אלא מזינים. לפי שהסבן במדבר גרם להם שעלו חמושים, שאלו הסיבן דרך ישוב לא היו מחמשים להם כל מה שצריכין, אלא כאדם שעובר ממקום למקום ובדעתו לקנות שם מה שיצטרך, אבל כשהוא פורש למדבר צריך לזמן לו כל הצרך, ומקרא זה לא נכתב כי אם לשבר את האזן, שלא תתמה במלחמת עמלק ובמלחמות סיחון ועוג ומדין, מהיכן היו להם כלי זין שהכום ישראל בחרב. וכן הוא אומר (יהושע א יד) ואתם תעברו חמשים. וכן תרגם אנקלוס מזרזין, כמו וירק את חניכיו (בראשית יד יד) וזריז. דבר אחר חמושים אחד מחמשה יצאו, וארבעה חלקים מתו בשלשת ימי אפלה:
@3 **השבע השביע.** השביעם שישביעו לבניהם. ולמה לא השביע את בניו שישאוהו לארץ כנען מיד, כמו שהשביעו יעקב, אמר יוסף אני שליט הייתי במצרים והיה ספק בידי לעשות, אבל בני לא יניחום מצרים לעשות, לכך השביעם לכשיגאלו ויצאו משם שישאוהו: **והעליתם את עצמתי מזה אתכם.** לאחיו השביע כן, למדנו שאף עצמות כל השבטים העלו עמהם, שנאמר אתכם:
@4 **ויסעו מסכת.** ביום השני, שהרי בראשון באו מרעמסס לסכות:
@5 **לנחתם הדרך.** נקוד פת''ח, שהוא כמו להנחותם, כמו (דברים א לג) לראותכם בדרך אשר תלכו בה, שהוא כמו להראותכם, אף כאן להנחותם על ידי שליח. ומי הוא השליח עמוד הענן, והקדוש ברוך הוא בכבודו מוליכו לפניהם. ומכל מקום את עמוד הענן הכין להנחותם על ידו, שהרי על ידי עמוד הענן הם הולכים, ועמוד הענן אינו לאורה אלא להורותם הדרך:
@6 **לא ימיש.** הקדוש ברוך הוא את עמוד הענן יומם ועמוד האש לילה. מגיד שעמוד הענן משלים לעמוד האש ועמוד האש משלים לעמוד הענן, שעד שלא ישקע זה עולה זה:
@8 **וישבו.** לאחוריהם לצד מצרים היו מקרבין כל יום השלישי כדי להטעות את פרעה שיאמר תועים הם בדרך, כמו שנאמר (פסוק ג) ואמר פרעה לבני ישראל וגו' : **ויחנו לפני פי החירת.** הוא פיתום, ועכשיו נקרא פי החירות על שם שנעשו בני חורין, והם שני סלעים גבוהים וזקופים, והגיא שביניהם קרוי פי הסלעים: **לפני בעל צפן.** הוא נשאר מכל אלהי מצרים, כדי להטעותן, שיאמרו קשה יראתן. ועליו פרש איוב (איוב יב כג) משגיא לגוים ויאבדם:
@9 **ואמר פרעה.** כשישמע שהם שבים לאחוריהם: **לבני ישראל.** על בני ישראל. וכן (פסוק יד) ה' ילחם לכם. עליכם, (בראשית כ יג) אמרי לי אחי הוא. אמרי עלי: **נבכים הם.** כלואים ומשקעים ובלעז שירי''ץ , כמו (תהלים פד ז) בעמק הבכא, (איוב כח יא) מבכי נהרות, (שם לח טז) נבכי ים. נבכים הם כלואים הם במדבר, שאינן יודעין לצאת ממנו ולהיכן ילכו:
@10 **ואכבדה בפרעה.** כשהקדוש ברוך הוא מתנקם ברשעים שמו מתגדל ומתכבד. וכן הוא אומר (יחזקאל לח כב) ונשפטתי אתו וגו' , ואחר כך (שם כג) והתגדלתי והתקדשתי ונודעתי וגו' , ואומר (תהלים עו ד) שמה שבר רשפי קשת, ואחר כך (שם פסוק ב) נודע ביהודה אלהים, ואומר (שם ט יז) נודע ה' משפט עשה: **בפרעה ובכל חילו.** הוא התחיל בעברה וממנו התחילה הפרענות: **ויעשו כן.** להגיד שבחן ששמעו לקול משה, ולא אמרו היאך נתקרב אל רודפינו, אנו צריכים לברוח, אלא אמרו אין לנו אלא דברי בן עמרם:
@11 **ויגד למלך מצרים.** איקטורין שלח עמהם, וכיון שהגיעו לשלשת ימים שקבעו לילך ולשוב וראו שאינן חוזרין למצרים, באו והגידו לפרעה ביום הרביעי. בחמישי ובששי רדפו אחריהם, וליל שביעי ירדו לים, בשחרית אמרו שירה, והוא יום שביעי של פסח, לכן אנו קורין השירה ביום השביעי: **ויהפך.** נהפך ממה שהיה, שהרי אמר להם (שמות יב לא) קומו צאו מתוך עמי, ונהפך לבב עבדיו, שהרי לשעבר היו אומרים לו (שם י ז) עד מתי יהיה זה לנו למוקש, ועכשיו נהפכו לרדוף אחריהם בשביל ממונם שהשאילום: **מעבדנו.** מעבוד אותנו:
@12 **ויאסר את רכבו.** הוא בעצמו: **ואת עמו לקח עמו.** משכם בדברים לקינו ונטלו ממוננו ושלחנום, בואו עמי ואני לא אתנהג עמכם כשאר מלכים, דרך שאר מלכים עבדיו קודמין לו במלחמה, ואני אקדים לפניכם, שנאמר (פסוק י) ופרעה הקריב, הקריב עצמו ומהר לפני חילותיו. דרך שאר מלכים לטול בזה בראש כמו שיבחר, אני אשוה עמכם בחלק, שנאמר (שמות טו ט) אחלק שלל:
@13 **בחור.** נבחרים, בחור לשון יחיד כל רכב ורכב שבמנין זה היה בחור: **וכל רכב מצרים.** ועמהם כל שאר הרכב ומהיכן היו הבהמות הללו, אם תאמר משל מצרים, הרי נאמר (שמות ט ו) וימת כל מקנה מצרים, ואם תאמר משל ישראל, והלא נאמר (שם י כו) וגם מקננו ילך עמנו. משל מי היו, מן הירא את דבר ה' (שם ט כ) . מכאן היה רבי שמעון אומר כשר שבמצרים הרוג, טוב שבנחשים רצוץ את מוחו: **ושלשם על כלו.** שרי צבאות כתרגומו:
@14 **ויחזק ה' את לב פרעה.** שהיה תולה אם לרדוף אם לאו. וחזק את לבו לרדוף: **ביד רמה.** גבורה גבוהה ומפרסמת:
@16 **ופרעה הקריב.** היה לו לכתוב ופרעה קרב, מהו הקריב, הקריב עצמו ונתאמץ לקדם לפניהם, כמו שהתנה עמהם: **נסע אחריהם.** בלב אחד כאיש אחד. דבר אחר והנה מצרים נוסע אחריהם, ראו שר של מצרים נוסע מן השמים לעזור למצרים. תנחומא: **ויצעקו.** תפשו אמנות אבותם. באברהם הוא אומר (בראשית יט כז) אל המקום אשר עמד שם, ביצחק (שם כד סג) לשוח בשדה, ביעקב (שם כח יא) ויפגע במקום:
@17 **המבלי אין קברים.** וכי מחמת חסרון קברים שאין קברים במצרים לקבר שם לקחתנו משם. ש''י פו''ר פיילנצ''א ד''י נו''ן פושי''ש בלעז :
@18 **אשר דברנו אליך במצרים.** והיכן דברו, (שמות ה כא) ירא ה' עליכם וישפוט: **ממתנו.** מאשר נמות, ואם היה נקוד מלאפו''ם היה נבאר ממיתתנו, עכשיו שנקוד בשור''ק נבאר מאשר נמות, וכן (להלן טז ג) מי יתן מותנו. שנמות, וכן (שמואל ב' יט א) מי יתן מותי, דאבשלום. שאמות, כמו (צפניה ג ח) ליום קומי לעד, (דברי הימים ב' יח כו) עד שובי בשלום, שאקום שאשוב:
@19 **כי אשר ראיתם את מצרים** וגו' **.** מה שראיתם אותם אינו אלא היום, היום הוא שראיתם אותם ולא תוסיפו עוד:
@20 **ה' ילחם לכם.** בשבילכם. וכן (פסוק כה) כי ה' נלחם להם, וכן (איוב יג ח) אם לאל תריבון, וכן (בראשית כד ז) ואשר דבר לי וכן (שופטים ו לא) האתם תריבון לבעל:
@21 **מה תצעק אלי.** למדנו שהיה משה עומד ומתפלל, אמר לו הקדוש ברוך הוא לא עת עתה להאריך בתפלה שישראל נתונין בצרה. דבר אחר מה תצעק אלי עלי הדבר תלוי ולא עליך, כמו שנאמר להלן (ישעיה מה יא) על בני ועל פעל ידי תצוני: **דבר אל בני ישראל ויסעו.** אין להם אלא לסע שאין הים עומד בפניהם, כדאי זכות אבותיהם והם והאמונה שהאמינו בי ויצאו, לקרוע להם הים:
@25 **וילך מאחריהם.** להבדיל בין מחנה מצרים ובין מחנה ישראל, ולקבל חצים ובליסטראות של מצרים. בכל מקום הוא אומר מלאך ה', וכאן מלאך האלהים, אין אלהים בכל מקום אלא דין, מלמד שהיו ישראל נתונין בדין באותה שעה אם להנצל אם להאבד עם מצרים: **ויסע עמוד הענן.** כשחשכה והשלים עמוד הענן את המחנה לעמוד האש, לא נסתלק הענן כמו שהיה רגיל להסתלק ערבית לגמרי, אלא נסע והלך לו מאחריהם להחשיך למצרים:
@26 **ויבא בין מחנה מצרים.** משל למהלך בדרך ובנו מהלך לפניו. באו לסטים לשבותו, נטלו מלפניו ונתנו לאחריו, באו זאבים מאחריו, נתנו לפניו, באו לסטים לפניו וזאבים מאחריו, נתנו על זרועו ונלחם בהם, כך (הושע יא ג) ואנכי תרגלתי לאפרים קחם על זרועותיו: **ויהי הענן והחשך.** למצרים: **ויאר.** עמוד האש את הלילה לישראל, והולך לפניהם כדרכו ללכת כל הלילה, והחשך של ערפל לצד מצרים: **ולא קרב זה אל זה.** מחנה אל מחנה:
@27 **ברוח קדים עזה.** ברוח קדים שהיא עזה שברוחות, היא הרוח שהקדוש ברוך הוא נפרע בה מן הרשעים, שנאמר (ירמיה יח יז) ברוח קדים אפיצם, (הושע יג טו) יבא קדים רוח ה', (יחזקאל כז כו) רוח הקדים שברך בלב ימים, (ישעיה כז ח) הגה ברוחו הקשה ביום קדים: **ויבקעו המים.** כל מים שבעולם:
@29 **כל סוס פרעה.** וכי סוס אחד היה אלא מגיד שאין כלם חשובין לפני המקום אלא כסוס אחד:
@30 **באשמרת הבקר.** שלשת חלקי הלילה קרויין אשמורות, ואותה שלפני הבקר קורא אשמורת הבקר. ואומר אני לפי שהלילה חלוק למשמרות שיר של מלאכי השרת, כת אחר כת לשלשה חלקים, לכך קרוי אשמורת, וזהו שתרגם אנקלוס במטרת: **וישקף.** ויבט, כלומר פנה אליהם להשחיתם, ותרגומו ואסתכי, אף הוא לשון הבטה, כמו (במדבר כג יד) שדה צופים. חקל סכותא: **בעמוד אש וענן.** עמוד ענן יורד ועושה אותו כטיט ועמוד אש מרתיחו, וטלפי סוסיהם משתמטות: **ויהם.** לשון מהומה, אישטורדישו''ן בלעז ערבבם, נטל סגניות שלהם. ושנינו בפרקי רבי אליעזר בנו של רבי יוסי הגלילי כל מקום שנאמר בו מהומה, הרעמת קול הוא, וזה אב לכלן (שמואל א' ז י) וירעם ה' בקול גדול וגו' על פלשתים ויהמם:
@31 **ויסר את אפן מרכבתיו.** מכח האש נשרפו הגלגלים והמרכבות נגררות, והיושבים בהם נעים ואיבריהן מתפרקין: **וינהגהו בכבדת.** בהנהגה שהיא כבדה וקשה להם, במדה שמדדו (שמות ט לד) ויכבד לבו הוא ועבדיו, אף כאן וינהגהו בכבדות: **נלחם להם במצרים.** במצרים. דבר אחר במצרים, בארץ מצרים, שכשם שאלו לוקים על הים, כך לוקים אותם שנשארו במצרים:
@32 **וישבו המים.** שזקופים ועומדים כחומה, ישובו למקומם ויכסו על מצרים:
@33 **לפנות בקר.** לעת שהבקר פונה לבא: **לאיתנו.** לתקפו הראשון: **נסים לקראתו.** שהיו מהממים ומטרפים ורצין לקראת המים: **וינער ה'.** כאדם שמנער את הקדרה והופך העליון למטה והתחתון למעלה, כך היו עולין ויורדין ומשתברין בים, ונתן הקדוש ברוך הוא בהם חיות לקבל היסורין: **וינער.** ושניק, והוא לשון טרוף בלשון ארמי והרבה יש במדרשי אגדה:
@34 **ויכסו את הרכב** וגו' **לכל חיל פרעה.** כך דרך המקראות לכתוב למ''ד יתרה, כמו (להלן כג) לכל כליו תעשה נחשת, וכן (שם יט) לכל כלי המשכן בכל עבודתו, (במדבר ד לב) ויתדותם ומיתריהם לכל כליהם, ואינה אלא תקון לשון:
@36 **וירא ישראל את מצרים מת.** שפלטן הים על שפתו, כדי שלא יאמרו ישראל כשם שאנו עולים מצד זה כך הם עולין מצד אחר רחוק ממנו וירדפו אחרינו:
@37 **את היד הגדלה.** את הגבורה הגדולה שעשתה ידו של הקדוש ברוך הוא. והרבה לשונות נופלין על לשון יד, וכלן לשון יד ממש הן, והמפרשו יתקן הלשון אחר ענין הדבור:
@38 **אז ישיר משה.** אז כשראה הנס עלה בלבו שישיר שירה, וכן (יהושע י יב) אז ידבר יהושע, וכן (מלכים א' ז ח) ובית יעשה לבת פרעה, חשב בלבו שיעשה לה, אף כאן ישיר, אמר לו לבו שישיר, וכן עשה, ויאמרו לאמר אשירה לה'. וכן ביהושע, כשראה הנס אמר לו לבו שידבר וכן עשה (יהושע י יב) ויאמר לעיני ישראל, וכן שירת הבאר שפתח בה (במדבר כא יז) אז ישיר ישראל, פרש אחריו עלי באר ענו לה. (מלכים יא ז) אז יבנה שלמה במה, פרשו בו חכמי ישראל שבקש לבנות ולא בנה. למדנו שהיו''ד על שם המחשבה נאמרה, זהו לישב פשוטו. אבל מדרשו אמרו רבותינו זכרונם לברכה, מכאן רמז לתחית המתים מן התורה, וכן בכלן חוץ משל שלמה, שפרשוהו, בקש לבנות ולא בנה. ואין לומר ולישב הלשון הזה כשאר דברים הנכתבים בלשון עתיד והן מיד, כגון (איוב א ה) ככה יעשה איוב, (במדבר ט כג) על פי ה' יחנו, (שם כ) ויש אשר יהיה הענן, לפי שהן דבר ההוה תמיד, ונופל בו בין לשון עתיד בין לשון עבר, אבל זה שלא היה אלא לשעה אינו יכול לישבו בלשון הזה: **כי גאה גאה.** שנתגאה על כל גאה כתרגומו. דבר אחר בא הכפל לומר שעשה דבר שאי אפשר לבשר ודם לעשות, כשהוא נלחם בחבירו ומתגבר עליו מפילו מן הסוס וכאן סוס ורוכבו רמה בים וכל שאי אפשר לעשות על ידי זולתו נופל בו לשון גאות, כמו (ישעיה יב ה) כי גאות עשה, וכן כל השירה תמצא כפולה (פסוק ב) עזי וזמרת יה ויהי לי לישועה (פסוק ג) ה' איש מלחמה ה' שמו, וכן כלם. דבר אחר כי גאה גאה על כל השירות, וכל מה שאקלס בו עוד יש בו תוספת, ולא כמדת מלך בשר ודם שמקלסין אותו ואין בו: **סוס ורכבו.** שניהם קשורין זה בזה והמים מעלין אותם לרום ומורידין אותם לעמק ואינן נפרדין: **רמה.** השליך וכן (דניאל ג ו) יתרמא לגוא אתון נורא. ומדרש אגדה כתוב אחד אומר רמה, וכתוב אחד אומר (פסוק ד) ירה, מלמד שהיו עולין לרום ויורדין לתהום, כמו (איוב לח ו) מי ירה אבן פנתה, מלמעלה למטה:
@39 **עזי וזמרת יה.** אונקלוס תרגם תוקפי ותושבחתי. עזי כמו עזי בשור''ק, וזמרת כמו וזמרתי. ואני תמה על לשון המקרא שאין לך כמוהו בנקדתו במקרא אלא בשלשה מקומות שהוא סמוך אצל וזמרת, וכל שאר מקומות נקוד שור''ק, (ירמיה טז יט) ה' עזי ומעזי, (תהלים נט י) עזו אליך אשמרה. וכן כל תבה בת שתי אותיות הנקודה מלאפו''ם כשהיא מארכת באות שלישית ואין השניה בשו''א בחטף, הראשונה נקודה בשור''ק כגון עז עזי, רק רקי, חק חקי, על עלו, יסור עלו (ישעיה י כז) , כל כלו ושלישים על כלו (לעיל יד ז) . ואלו שלושה עזי וזמרת של כאן, ושל ישעיה (ישעיה יב ב) ושל תהלים (תהלים קיח יד) נקודים בחטף קמ''ץ, ועוד אין באחד מהם כתוב וזמרתי אלא וזמרת, וכלם סמוך להם ויהי לי לישועה, לכך אני אומר לישב לשון המקרא, שאין עזי כמו עזי, ולא וזמרת כמו וזמרתי, אלא עזי שם דבר הוא, כמו (שם קכג א) היושבי בשמים, (עובדיה א ג) שוכני בחגוי סלע, (דברים לג טז) שוכני סנה. וזהו השבח עזי וזמרת יה הוא היה לי לישועה, וזמרת דבוק הוא לתיבת ה', כמו (שופטים ה כג) לעזרת ה', (ישעיה ט יח) בעברת ה', (קהלת ג יח) על דברת בני האדם. ולשון וזמרת לשון (ויקרא כה ד) לא תזמר, (ישעיה כה ה) זמיר עריצים, לשון כסוח וכריתה. עזו ונקמתו של אלהינו היה לנו לישועה. ואל תתמה על לשון ויהי שלא נאמר היה, שיש לנו כמה מקראות מדברים בלשון זה, וזה דגמתו (מלכים א ו ה) את קירות הבית סביב להיכל ולדביר ויעש צלעות סביב, היה לו לומר עשה צלעות סביב, וכן בדברי הימים (דברי הימים ב' י יז) ובני ישראל היושבים בערי יהודה וימלך עליהם רחבעם, היה לו לומר מלך עליהם רחבעם, (במד' יד טז) מבלתי יכולת ה' וגו' וישחטם, היה לו לומר שחטם, (שם לו. לז) והאנשים אשר שלח משה וגו' וימתו, מתו היה לו לומר, (שמות ט כא) ואשר לא שם לבו אל דבר ה' ויעזב, היה לו לומר עזב: **זה אלי.** בכבודו נגלה עליהם והיו מראין אותו באצבע, ראתה שפחה על הים מה שלא ראו נביאים: **ואנוהו.** אנקלוס תרגם לשון נוה, (ישעיה לג כ) נוה שאנן, (שם סה י) לנוה צאן. דבר אחר ואנוהו לשון נוי, אספר נויו ושבחו לבאי עולם, כגון (שיר השירים ה ט. י) מה דודך מדוד דודי צח ואדום, וכל הענין: **אלהי אבי.** הוא זה **וארוממנהו.** אלהי אבי, לא אני תחלת הקדשה, אלא מחזקת ועומדת לי הקדשה ואלהותו עלי מימי אבותי:
@40 **ה' איש מלחמה.** בעל מלחמות, כמו (רות א ג) איש נעמי, וכל איש ואישך מתרגמין בעל, וכן (מלכים א' ב ב) וחזקת והיית לאיש. לגבור: **ה' שמו.** מלחמותיו לא בכלי זין, אלא בשמו הוא נלחם, כמו שאמר דוד (שמואל א' יז מה) ואנכי בא אליך בשם ה' צבאות. דבר אחר ה' שמו אף בשעה שהוא נלחם ונוקם מאויביו, אוחז הוא במדתו לרחם על ברואיו ולזון את כל באי עולם, ולא כמדת מלכי אדמה כשהוא עוסק במלחמה פונה עצמו מכל עסקיו, ואין בו כח לעשות זו וזו:
@41 **ירה בים.** שדי בימא. שדי לשון יריה, וכן הוא אומר (שמות יט יג) או ירה יירה או אשתדאה ישתדי, והתי''ו משמשת באלו במקום יתפעל: **ומבחר.** שם דבר, כמו (ויקרא טו ט) מרכב, (שם ד) משכב, (שמות יב טז) מקרא קדש: **טבעו.** אין טביעה אלא במקום טיט, כמו (תהלים סט ג) טבעתי ביון מצולה, (ירמיה לח ו) ויטבע ירמיהו בטיט, מלמד שנעשה הים טיט לגמול להם כמדתם, ששעבדו את ישראל בחומר ובלבנים:
@42 **יכסימו.** כמו יכסום, והיו''ד האמצעית יתרה בו, ודרך המקראות בכך, כמו (דברים ח יג) ובקרך וצאנך ירבין, (תהלים לו ט) ירוין מדשן ביתך, והיו''ד ראשונה שמשמעה לשון עתיד כך פרשהו, טבעו בים סוף כדי שיחזרו המים ויכסו אותן. יכסימו אין דומה לו במקרא בנקדתו, ודרכו להיות נקוד יכסימו במלאפו''ם: **כמו אבן.** ובמקום אחר (פסוק י) צללו כעופרת, ובמקום אחר (פסוק ז) יאכלמו כקש, הרשעים כקש הולכים ומטרפין עולין ויורדין, בינונים כאבן, והכשרים כעופרת, שנחו מיד:
@43 **ימינך ימינך.** שתי פעמים, כשישראל עושין את רצונו של מקום השמאל נעשית ימין: **ימינך ה' נאדרי בכח.** להציל את ישראל וימינך השנית תרעץ אויב. ולי נראה אותה ימין עצמה תרעץ אויב, מה שאי אפשר לאדם לעשות שתי מלאכות ביד אחת. ופשוטו של מקרא ימינך הנאדרת בכח מה מלאכתה, ימינך היא תרעץ אויב, וכמה מקראות דגמתו (תהלים צב י) כי הנה אויביך ה' כי הנה אויביך יאבדו, (תהלים צד ג) עד מתי רשעים ה' עד מתי רשעים יעלזו, (תהלים צג ג) נשאו נהרות ה' נשאו נהרות קולם, (תהלים קטו א) לא לנו ה' לא לנו, (הושע ב כג) אענה נאם ה' אענה את השמים, (שופטים ה ג) אנכי לה' אנכי אשירה, (תהלים קכד א. ב) לולי ה' וכו' לולי ה' שהיה לנו בקום עלינו אדם, (שופטים ה יב) עורי עורי דבורה עורי עורי דברי שיר, (ישעי' כו ו) תרמסנה רגל רגלי עני, (תהלים קלו כא, כב) ונתן ארצם לנחלה וכו' נחלה לישראל: **נאדרי.** היו''ד יתרה, כמו (איכה א א) רבתי עם שרתי במדינות, (בראשית לא לט) גנבתי יום: **תרעץ אויב.** תמיד היא רועצת ומשברת האויב, ודומה לו (שופטים י ח) וירעצו וירוצצו את בני ישראל, בשופטים. דבר אחר ימינך הנאדרת בכח היא משברת ומלקה אויב:
@44 **וברב גאונך.** אם היד בלבד רועצת האויב, כשהוא מרומם ברוב גאונו, אז יהרס קמיו, ואם ברוב גאונו לבד אויביו נהרסים, קל וחומר כששלח בם חרון אף יאכלמו: **תהרס.** תמיד אתה הורס קמיך הקמים נגדך, ומי הם הקמים כנגדו, אלו הקמים על ישראל, וכן הוא אומר (תהל' פג ג) כי הנה אויביך יהמיון, ומה היא ההמיה, (שם ב) על עמך יערימו סוד, ועל זה קורא אותם אויביו של מקום:
@45 **וברוח אפיך.** היוצא משני נחירים של אף. דבר הכתוב כביכול בשכינה דגמת מלך בשר ודם, כדי להשמיע אזן הבריות כפי ההוה שיוכלו להבין דבר. כשאדם כועס יוצא רוח מנחיריו, וכן (תהלים יח ט) עלה עשן באפו, וכן (איוב ד ט) ומרוח אפו יכלו, וזהו שאמר (ישעיה מח ט) למען שמי אאריך אפי, כשזעפו נח נשמתו ארכה, וכשהוא כועס, נשמתו קצרה, (שם) ותהלתי אחטם לך, ולמען תהלתי אשים חטם באפי לסתום נחירי בפני האף והרוח שלא יצאו, לך בשבילך. אחטם כמו נאקה בחטם במסכת שבת (דף נא ב) כך נראה בעיני. וכל אף וחרון שבמקרא אני אומר כן, (דברים ז ד) חרה אף, כמו (איוב ל ל) ועצמי חרה מני חרב, לשון שרפה ומוקד, שהנחירים מתחממים ונחרים בעת הקצף, וחרון מגזרת חרה, כמו רצון מגזרת רצה, וכן חמה לשון חמימות, על כן הוא אומר (אסתר א יב) וחמתו בערה בו, ובנוח החמה אומר נתקררה דעתו: **נערמו מים.** אנקלוס תרגם לשון ערמימות ולשון צחות המקרא, כמו (שיר השירים ז ג) ערמת חטים, ונצבו כמו נד יוכיח. נערמו מים. ממוקד רוח שיצא מאפיך יבשו המים והם נעשו כמין גלים וכריות של ערמה שהם גבוהים: **כמו נד.** כתרגומו כשור, כחומה: **נד.** לשון צבור וכנוס, כמו (ישעיה יז יא) נד קציר ביום נחלה, (תהלים לג ז) כונס כנד, לא כתיב כנאד אלא כנד, ואלו היה כנד כמו כנאד. וכונס לשון הכנסה, היה לו לכתוב מכנס כבנאד מי הים, אלא כונס לשון אוסף וצובר הוא, וכן (יהושע ג טז) קמו נד אחד, (שם יג) ויעמדו נד אחד, ואין לשון קימה ועמידה בנאדות אלא בחומות וצבורים, ולא מצינו נאד נקוד אלא במלאפו''ם, כמו (תהלים נו ט) שימה דמעתי בנאדך, (שופטים ד יט) את נאד החלב: **קפאו.** כמו (איוב י י) וכגבנה תקפיאני, שהקשו ונעשו כאבנים והמים זורקים את המצרים על האבן בכח ונלחמים בם בכל מיני קושי: **בלב ים.** בחזק הים, ודרך המקראות לדבר כן (דברים ד יא) עד לב השמים, (שמואל ב' יח יד) בלב האלה, לשון עיקרו ותקפו של דבר:
@46 **אמר אויב.** לעמו כשפיתם בדברים, ארדוף ואשיגם ואחלק שלל עם שרי ועבדי: **תמלאמו.** תתמלא מהם: **נפשי.** רוחי ורצוני. ואל תתמה על תבה המדברת בשתים. תמלאמו תמלא מהם, יש הרבה כלשון הזה (שופטים א טו) כי ארץ הנגב נתתני, כמו נתת לי. (בראשית לז ד) ולא יכלו דברו לשלום, כמו דבר עמו. (ירמיה י כ) בני יצאוני, כמו יצאו ממני. (איוב לא לז) מספר צעדי אגידנו, כמו אגיד לו, אף כאן תמלאמו. תמלא נפשי מהם: **אריק חרבי.** אשלוף, ועל שם שהוא מריק את התער בשליפתו ונשאר ריק נופל בו לשון הרקה, כמו (בראשית מב לה) מריקים שקיהם, (ירמיה מח יב) וכליו יריקו. ואם תאמר אין לשון ריקות נופל על היוצא, אלא על התיק ועל השק ועל הכלי שיצא ממנה, אבל לא על החרב ועל היין, ולדחוק ולפרש אריק חרבי, כלשון (בראשית יד יד) וירק את חניכיו. אזדיין בחרבי, מצינו הלשון מוסב אף על היוצא (שיר השירים א ג) שמן תורק, (ירמיה מח יא) ולא הורק מכלי אל כלי, לא הורק הכלי אין כתיב כאן אלא לא הורק היין מכלי אל כלי, מצינו הלשון מוסב על היין. וכן (יחזקאל כח ז) והריקו חרבותם על יפי חכמתך, דחירם: **תורישמו.** לשון רישות ודלות, כמו (שמואל א' ב ז) מוריש ומעשיר:
@47 **נשפת.** לשון הפחה, וכן (ישעיה מ כד) וגם נשף בהם: **צללו.** שקעו, עמקו, לשון (תהלים סט ג) מצולה: **כעופרת.** אבר פלו''ם בלעז :
@48 **באלם.** בחזקים, כמו (יחזקאל יז יג) ואת אילי הארץ לקח, (תהלים כב כ) אילותי לעזרתי חושה: **נורא תהלת.** יראוי מלהגיד תהלותיו פן ימעטו, כמו שכתוב (שם סה ב) לך דמיה תהלה:
@49 **נטית ימינך.** כשהקדוש ברוך הוא נוטה ידו הרשעים כלים ונופלים, לפי שהכל נתון בידו נופלים בהטיתה וכן הוא אומר (ישעיה לא ג) וה' יטה ידו וכשל עוזר ונפל עזר. משל לכלי זכוכית הנתונים בידי אדם, מטה ידו מעט והן נופלין ומשתברין: **תבלעמו ארץ.** מכאן שזכו לקבורה בשכר שאמרו (לעיל ט כז) ה' הצדיק:
@50 **נהלת.** לשון מנהל, ואונקלוס תרגם לשון נושא וסובל, ולא דקדק לפרש אחר לשון העברית:
@51 **ירגזון.** מתרגזין: **ישבי פלשת.** מפני שהרגו את בני אפרים שמהרו את הקץ ויצאו בחזקה, כמפורש בדברי הימים (דברי הימים א' ז כא) והרגום אנשי גת:
@52 **אלופי אדום אילי מואב.** והלא לא היה להם לירא כלום, שהרי לא עליהם הולכים, אלא מפני אנינות שהיו מתאוננים ומצטערים על כבודם של ישראל: **נמגו.** נמסו, כמו (תהלים סה יא) ברביבים תמגגנה. אמרו עלינו הם באים לכלותינו ולירש את ארצנו:
@53 **תפל עליהם אימתה.** על הרחוקים: **ופחד.** על הקרובים, כענין שנאמר (יהושע ב י) כי שמענו את אשר הוביש וגו' : **עד יעבר עד יעבר.** כתרגומו: **קנית.** חבבת משאר אמות, כחפץ הקנוי בדמים יקרים, שחביב על האדם:
@54 **תבאמו.** נתנבא משה שלא יכנס לארץ לכך לא נאמר תביאנו: **מכון לשבתך.** מקדש של מטה מכון כנגד כסא של מעלה אשר פעלת: **מקדש.** הטעם עליו זקף גדול להפרידו מתבת השם של אחריו המקדש אשר כוננו ידיך ה'. חביב בית המקדש שהעולם נברא ביד אחת, שנאמר (ישע' מח יג) אף ידי יסדה ארץ, ומקדש בשתי ידים. ואימתי יבנה בשתי ידים, בזמן שה' ימלך לעלם ועד, לעתיד לבא שכל המלוכה שלו:
@55 **לעלם ועד.** לשון עולמות הוא והוי''ו בו יסוד לפיכך היא פתוחה, אבל (ירמיה כט כג) ואנכי היודע ועד, שהוי''ו בו שמוש, קמוצה היא:
@56 **כי בא סוס פרעה.** כאשר בא:
@57 **ותקח מרים הנביאה.** היכן נתנבאה כשהיתה אחות אהרן, קדם שנלד משה, אמרה עתידה אמי שתלד בן וכו' , כדאיתא בסוטה (דף יג א) . דבר אחר אחות אהרן לפי שמסר נפשו עליה כשנצטרעה, נקראת על שמו: **את התף.** כלי של מיני זמר: **בתפים ובמחלת.** מבטחות היו צדקניות שבדור שהקדוש ברוך הוא עושה להם נסים והוציאו תפים ממצרים:
@58 **ותען להם מרים.** משה אמר שירה לאנשים, הוא אומר והם עונין אחריו, ומרים אמרה שירה לנשים:
@59 **ויסע משה.** הסיען בעל כרחם שעטרו מצרים סוסיהם בתכשיטי זהב וכסף ואבנים טובות, והיו ישראל מוצאין אותם בים, וגדולה היתה בזת הים מבזת מצרים, שנאמר (שיר השירים א יא) תורי זהב נעשה לך עם נקדות הכסף, לפיכך הצרך להסיען בעל כרחם:
@60 **ויבאו מרתה.** כמו למרה, ה''א בסוף תבה במקום למ''ד בתחלתה, והתי''ו היא במקום ה''א הנשרשת בתיבת מרה, ובסמיכתה כשהיא נדבקת לה''א, שהוא מוסיף במקום הלמ''ד, תהפך הה''א של שרש לתי''ו, וכן כל ה''א שהיא שרש בתבה, תתהפך לתי''ו בסמיכתה, כמו (ישעיה כז ד) חמה אין לי, (אסתר א יב) וחמתו בערה בו, הרי ה''א של שרש נהפכת לתי''ו, מפני שנסמכת אל הו''ו הנוספת, וכן (ויקרא כה מד) עבד ואמה, (בראשית ל ג) הנה אמתי בלהה, (שם ב ז) לנפש חיה, (איוב לג כ) וזהמתו חיתו לחם, (שופטים ד ה) בין הרמה, (שמואל א' ז יז) ותשובתו הרמתה:
@61 **וילנו.** לשון נפעל הוא וכן התרגום לשון נפעל הוא ואתרעמו. כן דרך לשון תלנה להסב הדבור אל האדם מתלונן מתרועם, ולא אמר, לונן, רועם, וכן יאמר הלועז דיקומפליינש''ט שי''י , מוסב הדבור אליו באמרו שי''י [עצמו] :
@62 **שם שם לו.** במרה נתן להם מקצת פרשיות של תורה שיתעסקו בהם, שבת ופרה אדמה ודינין: **ושם נסהו.** לעם, וראה קשי ערפן שלא נמלכו במשה בלשון יפה, בקש עלינו רחמים שיהיה לנו מים לשתות, אלא נתלוננו:
@63 **אם שמוע תשמע.** זו קבלה שיקבלו עליהם: **תעשה.** היא עשיה: **והאזנת.** תטה אזנים לדקדק בהם: **כל חקיו.** דברים שאינן אלא גזרת מלך בלא שום טעם, ויצר הרע מקנטר עליהם מה אסור באלו, למה נאסרו, כגון לבישת כלאים ואכילת חזיר ופרה אדמה וכיוצא בהם: **לא אשים עליך.** ואם אשים הרי היא כלא הושמה, כי אני ה' רופאך, זהו מדרשו. ולפי פשוטו כי אני ה' רופאך ומלמדך תורה ומצות למען תנצל מהם, כרופא הזה האומר לאדם אל תאכל דבר זה פן יביאך לידי חולי זה וכן הוא אומר (משלי ג ח) רפאות תהי לשרך:
@64 **שתים עשרה עינת מים.** כנגד שנים עשר שבטים נזדמנו להם: **ושבעים תמרים.** כנגד שבעים זקנים:
@65 **בחמשה עשר יום.** נתפרש היום של חניה זו, לפי שבו ביום כלתה החררה שהוציאו ממצרים והצרכו למן, למדנו שאכלו משירי הבצק [משירי המצה] ששים ואחת סעודות, וירד להם מן בששה עשר באיר ויום ראשון בשבת היה, כדאיתא במסכת שבת (דף פז ב) :
@66 **וילונו.** לפי שכלה הלחם:
@67 **מי יתן מותנו.** שנמות, ואינו שם דבר כמו מותנו אלא כמו עשותנו, חנותנו, שובנו, לעשות אנחנו, לחנות אנחנו, למות אנחנו. ותרגומו לוי דמיתנא, כמו (במדבר יד ב) לו מתנו, הלואי והיינו מתים:
@68 **דבר יום ביומו.** צורך אכילת יום ילקטו ביומו, ולא ילקטו היום לצורך מחר: **למען אנסנו הילך בתורתי.** אם ישמרו מצות התלויות בו, שלא יותירו ממנו ולא יצאו בשבת ללקוט:
@69 **והיה משנה.** ליום ולמחרת: **משנה.** על שהיו רגילים ללקוט יום יום של שאר ימות השבוע. ואומר אני אשר יביאו והיה משנה, לאחר שיביאו ימצאו משנה במדידה על אשר ילקטו וימדו יום יום וזהו (להלן פסוק כב) לקטו לחם משנה, בלקיטתו היה נמצא לחם משנה. וזהו (להלן פסוק כט) על כן הוא נותן לכם ביום הששי לחם יומים, נותן לכם ברכה פוישו''ן [שפע] בבית למלאות העמר פעמים ללחם יומים:
@70 **ערב.** כמו לערב: **וידעתם כי ה' הוציא אתכם מארץ מצרים.** לפי שאמרתם לנו כי הוצאתם אותנו, תדעו כי לא אנחנו המוציאים אלא ה' הוציא אתכם, שיגיז לכם את השליו:
@71 **ובקר וראיתם.** לא על הכבוד שנאמר (להלן פסוק י) והנה כבוד ה' נראה בענן, נאמר, אלא כך אמר להם ערב וידעתם כי היכולת בידו לתן תאותכם ובשר יתן, אך לא בפנים מאירות יתננה לכם, כי שלא כהוגן שאלתם אותו ומכרס מלאה, והלחם ששאלתם לצורך, בירידתו לבקר תראו את כבוד אור פניו שיורידהו לכם דרך חבה בבקר, שיש שהות להכינו וטל מלמעלה וטל מלמטה כמנח בקפסא: **את תלנתיכם על ה'.** כמו אשר על ה': **ונחנו מה.** מה אנחנו חשובין: **כי תלינו עלינו.** שתרעימו עלינו את הכל, את בניכם ונשיכם ובנותיכם וערב רב, ועל כרחי אני זקוק לפרש תלינו בלשון תפעילו מפני דגשותו וקריתו, שאלו היה רפה הייתי מפרשו בלשון תפעלו, כמו (שמות יז ג) וילן העם על משה, או אם היה דגוש ואין בו יו''ד ונקרא תלונו, הייתי מפרשו לשון תתלוננו, עכשיו הוא משמע תלינו את אחרים, כמו במרגלים (במדבר יד לו) וילינו עליו את כל העדה:
@72 **בשר לאכל.** ולא לשבע, למדה תורה דרך ארץ שאין אוכלין בשר לשבע. ומה ראה להוריד לחם בבקר ובשר בערב, לפי שהלחם שאלו כהוגן, שאי אפשר לו לאדם בלא לחם, אבל בשר שאלו שלא כהוגן, שהרבה בהמות היו להם. ועוד, שהיה אפשר להם בלא בשר, לפיכך נתן להם בשעת טרח, שלא כהוגן: **אשר אתם מלינם עליו.** את האחרים השומעים אתכם מתלוננים:
@73 **קרבו.** למקום שהענן ירד:
@77 **השלו.** מין עוף ושמן מאד: **היתה שכבת הטל.** הטל שוכב על המן ובמקום אחר הוא אומר (במדבר יא ט) וברדת הטל וגו' הטל יורד על הארץ והמן יורד עליו, וחוזר ויורד טל עליו והרי הוא כמנח בקפסא:
@78 **ותעל שכבת הטל** וגו' **.** כשהחמה זורחת עולה הטל שעל המן לקראת החמה, כדרך טל עולה לקראת החמה, אף אם תמלא שפופרת של ביצה טל, ותסתום את פיה ותניחה בחמה, היא עולה מאליה באויר. ורבותינו דרשו שהטל עולה מן הארץ באויר, וכעלות שכבת הטל נתגלה המן וראו והנה על פני המדבר וגו' : **דק.** דבר דק: **מחספס.** מגלה, ואין דומה לו במקרא. ויש לפרש מחספס לשון חפיסא ודלוסקמא שבלשון משנה. כשנתגלה משכבת הטל ראו שהיה דבר דק מחספס בתוכו בין שתי שכבות הטל. ואונקלוס תרגם מקלף, לשון (בראשית ל לז) מחשוף הלבן: **ככפר.** כפור ייליד''ה בלע''ז דעדק כגיר (ישעיה כז ט) כאבני גיר והוא מין צבע שחור, כדאמרינן גבי כסוי הדם (חולין פח ב) הגיר והזרניך. דעדק כגיר כגלידא על ארעא, דק היה כגיר ושוכב מגלד כקרח על הארץ. וכן פרוש דק ככפור, שטוח קלוש ומחבר כגליד. דק טינבי''ש בלעז , שהיה מגליד גלד דק מלמעלה. וכגיר שתרגם אנקלוס, תוספת הוא על לשון העברית, ואין לו תבה בפסוק:
@79 **מן הוא.** הכנת מזון הוא, כמו (דניאל א ה) וימן להם המלך: **כי לא ידעו מה הוא.** שיקראוהו בשמו:
@80 **עמר.** שם מדה: **מספר נפשתיכם.** כפי מנין נפשות שיש לאיש באהלו תקחו עמר לכל גלגלת:
@81 **המרבה והממעיט.** יש שלקטו הרבה ויש שלקטו מעט וכשבאו לביתם ומדדו בעומר, איש איש מה שלקטו, ומצאו שהמרבה ללקוט לא העדיף על עמר לגלגלת אשר באהלו, והממעיט ללקוט לא מצא חסר מעומר לגלגלת, וזהו נס גדול שנעשה בו:
@84 **ויותרו אנשים.** דתן ואבירם: **וירם תולעים.** לשון רמה: **ויבאש.** הרי זה מקרא הפוך, שתחלה הבאיש ולבסוף התליע, כענין שנאמר (פסוק כד) ולא הבאיש ורמה לא היתה בו, וכן דרך כל המתליעים:
@85 **וחם השמש ונמס.** הנשאר בשדה נמוח (י''ג: נמוח) ונעשה נחלים, ושותין ממנו אילים וצבאים, ואמות העולם צדין מהם וטועמין בהם טעם מן, ויודעין מה שבחן של ישראל. ותרגומו של נמס פשר, לשון פושרין, על ידי השמש מתחמם ומפשיר דישטיפרי''ר ודגמתו בסנהדרין [ סז ] בסוף ארבע מיתות:
@86 **לקטו לחם משנה.** כשמדדו את לקיטתם באהליהם מצאו כפלים שני העמר לאחד. ומדרש אגדה לחם משנה משנה. אותו היום נשתנה לשבח בריחו וטעמו: **ויגידו למשה.** שאלוהו מה היום מיומים, ומכאן יש ללמוד שעדין לא הגיד להם משה פרשת שבת שנצטוה לומר להם (פסוק ה) והיה ביום הששי והכינו וגו' , עד ששאלו את זאת, אמר להם (פסוק כג) הוא אשר דבר ה', שנצטויתי לומר לכם, ולכך ענשו הכתוב, שאמר לו (פסוק כח) עד אנה מאנתם, ולא הוציאו מן הכלל:
@87 **את אשר תאפו אפו.** מה שאתם רוצים לאפות בתנור, אפו היום, הכל לשני ימים, ומה שאתם צריכים לבשל ממנו במים, בשלו היום. לשון אפיה נופל בלחם, ולשון בשול בתבשיל: **למשמרת.** לגניזה:
@89 **ויאמר משה אכלהו היום כי שבת היום.** שחרית שהיו רגילים לצאת וללקוט, באו לשאול אם נצא אם לאו, אמר להם את שבידכם אכלו. לערב חזרו לפניו ושאלוהו מהו לצאת, אמר להם שבת היום. ראה אותם דואגים שמא פסק המן ולא ירד עוד, אמר להם היום לא תמצאהו. מה תלמוד לומר היום, היום לא תמצאהו אבל מחר תמצאהו:
@90 **וביום השביעי שבת.** שבת הוא, המן לא יהיה בו, ולא בא הכתוב אלא לרבות יום הכפורים וימים טובים:
@92 **עד אנה מאנתם.** משל הדיוט הוא, בהדי הוצא לקי כרבא, על ידי הרשעים מתגנין הכשרין:
@93 **ראו.** בעיניכם כי ה' בכבודו מזהיר אתכם על השבת, שהרי נס נעשה בכל ערב שבת לתת לכם לחם יומים: **שבו איש תחתיו.** מכאן סמכו חכמים ארבע אמות ליוצא חוץ לתחום: **אל יצא איש ממקמו.** אלו אלפים אמה של תחום שבת, ולא במפורש, שאין תחומין אלא מדברי סופרים, ועיקרו של מקרא על לוקטי המן נאמר:
@95 **והוא כזרע גד לבן.** עשב ששמו אליינדר''א [כוסבר] וזרע שלו עגול ואינו לבן, והמן היה לבן, ואינו נמשל לזרע גד אלא לענין העגול כזרע גד היה, והוא לבן: **כצפיחת.** בצק שמטגנין אותו בדבש וקורין לו אסקריטון בלשון משנה והוא תרגום של אנקלוס:
@96 **למשמרת.** לגניזה: **לדרתיכם.** בימי ירמיהו כשהיה ירמיהו מוכיחם, למה אין אתם עוסקים בתורה והם אומרים נניח מלאכתנו ונעסוק בתורה, מהיכן נתפרנס, הוציא להם צנצנת המן ואמר להם (ירמיה ב לא) הדור אתם ראו דבר ה', שמעו לא נאמר אלא ראו, בזה נתפרנסו אבותיכם, הרבה שלוחין יש לו למקום להכין מזון ליראיו:
@97 **צנצנת.** צלוחית של חרס, כתרגומו: **והנח אתו לפני ה'.** לפני הארון, ולא נאמר מקרא זה עד שנבנה אהל מועד, אלא שנכתב כאן בפרשת המן:
@99 **ארבעים שנה.** והלא חסר שלשים יום, שהרי בחמשה עשר באיר ירד להם המן תחלה, ובחמשה עשר בניסן פסק, שנאמר (יהושע ה יב) וישבת המן ממחרת, אלא מגיד שהעוגות שהוציאו ישראל ממצרים טעמו בהם טעם מן: **אל ארץ נושבת.** לאחר שעברו את הירדן שאותה שבעבר הירדן מישבת וטובה, שנאמר (דברים ג כה) אעברה נא ואראה את הארץ הטובה אשר בעבר הירדן, ותרגום של נושבת יתבתא, רצה לומר מישבת: **אל קצה ארץ כנען.** בתחלת הגבול, קדם שעברו את הירדן, והוא ערבות מואב. נמצאו מכחישין זה את זה, אלא בערבות מואב כשמת משה בשבעה באדר פסק המן מלירד, ונסתפקו ממן שלקטו בו ביום עד שהקריבו העמר בששה עשר בניסן, שנאמר (יהושע ה יא) ויאכלו מעבור הארץ ממחרת הפסח:
@100 **עשרית האיפה.** האיפה שלש סאין, והסאה ששה קבין והקב ארבעה לוגין והלוג שש ביצים נמצא עשירית האיפה ארבעים ושלש ביצים וחמש ביצה והוא שעור לחלה ולמנחות:
@102 **מה תנסון.** לומר היוכל לתת מים בארץ ציה:
@104 **עוד מעט.** אם אמתין עוד מעט וסקלני:
@105 **עבר לפני העם.** וראה אם יסקלוך, למה הוצאת לעז על בני: **וקח אתך מזקני ישראל.** לעדות שיראו שעל ידך המים יוצאים מן הצור, ולא יאמרו מעינות היו שם מימי קדם: **ומטך אשר הכית בו את היאר.** מה תלמוד לומר אשר הכית בו את היאור, אלא שהיו ישראל אומרים על המטה שאינו מוכן אלא לפרענות, בו לקה פרעה ומצרים כמה מכות במצרים ועל הים, לכן נאמר אשר הכית בו את היאר, יראו עתה שאף לטובה הוא מוכן:
@106 **והכית בצור.** על הצור לא נאמר אלא בצור, מכאן שהמטה היה של מין דבר חזק ושמו סנפרינון והצור נבקע מפניו:
@108 **ויבא עמלק** וגו' **.** סמך פרשה זו למקרא זה, לומר תמיד אני ביניכם ומזמן לכל צרכיכם, ואתם אומרים (פסוק ז) היש ה' בקרבנו אם אין, חייכם שהכלב בא ונושך אתכם ואתם צועקים אלי ותדעון היכן אני. משל לאדם שהרכיב בנו על כתפו ויצא לדרך, היה אותו הבן רואה חפץ ואומר, אבא טול חפץ זה ותן לי, והוא נותן לו, וכן שניה וכן שלישית, פגעו באדם אחד, אמר לו אותו הבן ראית את אבא. אמר לו אביו אינך יודע היכן אני, השליכו מעליו ובא הכלב ונשכו:
@109 **בחר לנו.** לי ולך, השוהו לו, מכאן אמרו יהי כבוד תלמידך חביב עליך כשלך וכבוד חברך כמורא רבך, מנין שנאמר (במדבר יב יא) ויאמר אהרן אל משה בי אדני והלא אהרן גדול מאחיו היה ועושה את חברו כרבו. ומורא רבך כמורא שמים מנין, שנאמר (שם יא כח) אדני משה כלאם, כלם מן העולם, חייבין הם כליה, המורדים בך, כאלו מרדו בהקדוש ברוך הוא: **וצא הלחם.** צא מן הענן והלחם בו: **מחר.** בעת המלחמה אנכי נצב: **בחר לנו אנשים.** גבורים ויראי חטא שתהא זכותן מסיעתן. דבר אחר בחר לנו אנשים שיודעין לבטל כשפים לפי שבני עמלק מכשפין היו:
@110 **ומשה אהרן וחור.** מכאן לתענית שצריכים שלשה לעבור לפני התבה, שבתענית היו שרוים: **חור.** בנה של מרים היה וכלב בעלה:
@111 **כאשר ירים משה ידו.** וכי ידיו של משה נוצחות היו המלחמה וכו' כדאיתא בראש השנה (כט א) :
@112 **וידי משה כבדים.** בשביל שנתעצל במצוה ומנה אחר תחתיו, נתיקרו ידיו: **ויקחו.** אהרן וחור: **אבן וישימו תחתיו.** ולא ישב לו על כר וכסת. אמר ישראל שרויין בצער, אף אני אהיה עמהם בצער: **ויהי ידיו אמונה.** ויהי משה ידיו באמונה פרושות השמים בתפלה נאמנה ונכונה: **עד בא השמש.** שהיו עמלקים מחשבין את השעות באצטרולוגיאה באיזו שעה הם נוצחים, והעמיד להם משה חמה וערבב את השעות:
@113 **ויחלש יהושע.** חתך ראשי גבוריו ולא השאיר אלא חלשים שבהם ולא הרגם כלם, מכאן אנו למדין שעשה על פי הדבור של שכינה:
@114 **כתב זאת זכרון.** שבא עמלק להזדוג לישראל קדם לכל האמות: **ושים באזני יהושע.** המכניס את ישראל לארץ, שיצוה את ישראל לשלם לו את גמולו, כאן נרמז לו למשה שיהושע מכניס את ישראל לארץ: **כי מחה אמחה.** לכך אני מזהירך כן, כי חפץ אני למחותו:
@115 **ויקרא שמו.** של מזבח: **ה' נסי.** הקדוש ברוך הוא עשה לנו כאן נס גדול, לא שהמזבח קרוי ה', אלא המזכיר שמו של מזבח זוכר את הנס שעשה המקום, ה' הוא נס שלנו:
@116 **ויאמר.** משה: **כי יד על כס יה.** ידו של הקדוש ברוך הוא הרמה לשבע בכסאו להיות לו מלחמה ואיבה בעמלק עולמית, ומהו כס, ולא נאמר כסא, ואף השם נחלק לחציו, נשבע הקדוש ברוך הוא שאין שמו שלם ואין כסאו שלם עד שימחה שמו של עמלק כלו, וכשימחה שמו יהיה השם שלם והכסא שלם, שנאמר (תהלים ט ז) האויב תמו חרבות לנצח, זהו עמלק שכתוב בו (עמוס א יא) ועברתו שמרה נצח, (תהלים שם) וערים נתשת אבד זכרם המה, מהו אומר אחריו (תהלים ט ח) וה' לעולם ישב, הרי השם שלם, (תהלים שם) כונן למשפט כסאו, הרי כסאו שלם:

@1 **כי קרוב הוא** . ונח לשוב באותו הדרך למצרים, ומדרשי אגדה יש הרבה. לשון רש''י. וגם הוא דעת ר''א, כי טעם **ולא נחם אלהים דרך ארץ פלשתים** בעבור **כי קרוב הוא** וינחמו וישובו אל מצרים מיד. ועל דעתי אם היה כדבריהם, היה **כי אמר אלהים** מוקדם, ויאמר הכתוב **ולא נחם אלהים דרך ארץ פלשתים כי אמר אלהים כי קרוב הוא פן ינחם העם** :
@1 **אבל** הנכון שיאמר **ולא נחם אלהים דרך ארץ פלשתים** אשר הוא קרוב וטוב לנחותם בדרך ההוא, **כי אמר אלהים פן ינחם העם בראותם מלחמה ושבו מצרימה** . וטעם המלחמה, שיהיה להם לעבור דרך ארץ פלשתים, ופלשתים לא יתנום לעבור בשלום וישובו למצרים, אבל בדרך המדבר לא יראו מלחמה עד היותם בארצם בארץ סיחון ועוג מלכי האמורי שהיא נתונה להם ורחוקים הם ממצרים בעת ההיא. **ומלחמת** עמלק ברפידים לא היתה ראויה לשוב בעבורה, כי הם לא יעברו עליהם, והוא שבא מארצו ונלחם בהם לשנאתו אותם, ואם יתנו ראש לשוב למצרים לא יועיל כי ילחם בהם בדרך, וגם רחוקים היו ממצרים בדרך העקום אשר הלכו בה ולא ידעו דרך אחרת:
@1 **ולשון** רש''י **בראותם מלחמה** , כגון מלחמת הכנעני והעמלקי, אם הלכו בדרך ישרה היו חוזרין, מה אם כשהקיפם דרך מעוקם אמרו נתנה ראש ונשובה מצרימה, אם הוליכן בפשוטה על אחת כמה וכמה. מכילתא. והענין הזה שאמר **ולא נחם אלהים** , **ויסב אלהים את העם דרך המדבר** , כי בנסעם מסכות החל עמוד הענן ללכת לפניהם ולא הלך דרך ארץ פלשתים, אבל הלך דרך מדבר איתם וישראל הלכו אחריו, וישכון הענן באיתם ויחנו שם והוא בקצה המדבר:
@2 וטעם **וחמושים עלו בני ישראל** . לומר כי אע''פ שהסב ה' אותם דרך המדבר היו יראים פן יבאו עליהם פלשתים יושבי הערים הקרובות להם והיו חלוצים כמו היוצאים למלחמה. ויש אומרים (ראב''ע) שספר הכתוב שיצאו ביד רמה וחשבו להיות גאולים, ולא הלכו כדמות עבדים בורחים:
@5 **וה' הולך לפניהם יומם** . כבר אמרו (ב''ר נא ב) שכל מקום שנאמר **וה'** הוא ובית דינו, הקב''ה עמהם ביום ובית דינו בלילה. אם כן פירוש הכתוב שהשם שוכן בתוך הענן והולך הוא לפניהם ביום בעמוד ענן, ובלילה בית דינו שוכן בעמוד האש להאיר להם, כטעם אשר עין בעין נראה אתה ה' ועננך עומד עליהם ובעמוד ענן אתה הולך לפניהם יומם ובעמוד אש לילה (במדבר יד יד):
@5 **וראיתי** באלה שמות רבה (יט ו) כי לא בחפזון תצאו ובמנוסה לא תלכון כי הולך לפניכם ה' (ישעיה נב יב), לשעבר אני ובית דיני הייתי מהלך לפניכם, שנאמר **וה' הלך לפניהם יומם** , אבל לעתיד לבא אני לבדי, שנאמר (ישעיה נב יב) כי הולך לפניכם ה' ומאספכם אלהי ישראל. וסוד המדרש הזה כאשר הזכרתי, כי בגאולה הראשונה היה הקב''ה עמהם ביום ובית דינו עמהם בלילה, אבל לעתיד לבא תתעלה מדת בית דינו ברחמים, **וה' הולך לפניהם** , השם המיוחד, כי אלהי ישראל מאספם עמו, ולילה כיום יאיר כחשכה כאורה (תהלים קלט יב), כי הכל במדת רחמים מיוחדת:
@5 **ור''א** אמר כי הכתוב ידבר הוא כלשון בני האדם, בעבור כי כח השם ושלוחו הוא הולך עם ישראל כדרך מוליך לימין משה זרוע תפארתו (ישעיה סג יב). והאמת שהוא כדרך מוליך לימין משה, אבל לא כאשר יבין ר''א ממנו, וכתיב כן נהגת עמך לעשות לך שם תפארת (שם יד):
@10 **וחזקתי את לב פרעה ורדף אחריהם** . בעבור שפחד פרעה מהם במכת הבכורות ובקש מהם וברכתם גם אותי (לעיל יב לב), לא היה בלבו לרדוף אחריהם אפילו אם יברחו, אלא שיעשה משה בהם כרצונו, ועל כן הוצרך לומר כי הוא יחזק את לבו לרדוף אחריהם. **ולמטה** (פסוק יז) אמר פעם אחרת הנני מחזק את לב מצרים ויבאו אחריהם, כי בראותם שנקרע הים לפני בני ישראל והם הולכים ביבשה בתוכו איך ימלאם לבם לבא אחריהם להרע להם, ואין בכל המופתים כפלא הזה, וזה באמת שגעון להם, אבל סכל עצתם וחזק את לבם ליכנס בים:
@11 **ויוגד למלך מצרים כי ברח העם** . איקטורין שלח עמהם, וכיון שהגיעו עד שלשת ימים שקבעו לילך ולשוב וראו שאינם חוזרים למצרים חזרו והגידו לפרעה ביום הרביעי, חמישי וששי רדפו אחריהם, ליל שביעי ירדו לים, בשחרית אמרו שירה, והוא יום שביעי של פסח, לכך אנו קורין השירה ביום השביעי. זהו לשון רש''י. וכן הוא במכילתא (כאן). ועל דרך הפשט הוא אשר דבר ה' ואמר פרעה לבני ישראל, כי כאשר עשו כן בני ישראל ושבו וחנו לפני פי החירות לפני בעל צפון הוגד זה למלך מצרים ואמר כי ברח העם והם נבוכים במדבר ואינם הולכים אל ידוע לזבוח. וזה טעם ובני ישראל יוצאים ביד רמה (פסוק ח), שעשו להם דגל ונס להתנוסס, ויוצאים בשמחה ובשירים בתוף ובכנור כדמות הנגאלים מעבדות לחירות, לא כעבדים העתידים לשוב לעבודתם, וכל זה הוגד לו:
@16 (י~יא) **וייראו מאד ויצעקו בני ישראל אל ה'** , **ויאמרו אל משה המבלי אין קברים במצרים** . איננו נראה כי בני אדם הצועקים אל ה' להושיעם יבעטו בישועה אשר עשה להם ויאמרו כי טוב להם שלא הצילם. אבל הנכון שנפרש כי היו כתות, והכתוב יספר כל מה שעשו כלם. אמר כי הכת האחת צועקת אל ה', והאחת מכחשת בנביאו ואינה מודה בישועה הנעשית להם, ויאמרו כי טוב להם שלא הצילם. ועל זאת כתוב וימרו על ים בים סוף (תהלים קו ז), ולכך יחזיר הכתוב ''בני ישראל'' פעם אחרת, **ויצעקו בני ישראל אל ה'** , כי הטובים בהם צעקו אל ה' והנשארים מרו בדברו. ולכך אמר אח''כ (להלן פסוק לא) וייראו העם את ה' ויאמינו בה' ובמשה עבדו. לא אמר ''וייראו ישראל את ה' ויאמינו'' אבל אמר ''העם'', כי ''בני ישראל'' שם ליחידים, ו''העם'' שם להמון, וכן וילונו העם (להלן טו כד). וכך הזכירו רבותינו (במדב''ר כ כג) ויחל העם לזנות (במדבר כה א), בכל שנאמר ''העם'' לשון גנאי הוא, וכל מקום שנאמר ''ישראל'' לשון שבח הוא:
@16 **והנה** לא אמרו ''לקחתנו למות במלחמה'', אבל **לקחתנו למות במדבר** , **וממותנו במדבר** , כי טרם יראו מלחמה לא היו חפצים לצאת אל המדבר פן ימותו שם ברעב ובצמא. ויתכן שאמרו לו כן בצאתם ועודם בארץ מצרים כאשר הסב אותם אלהים דרך המדבר ים סוף. או שאמרו לו מתחלה אנה נצא, אם דרך פלשתים ילחמו בנו, ואם דרך המדבר **טוב לנו לעבוד את מצרים ממותנו במדבר ואפשר** עוד לומר כי היו העם מאמינים בה' ומתפללים אליו להצילם, אבל במשה נכנס ספק בלבם פן יוציאם למשול עליהם. ואע''פ שראו האותות והמופתים חשבו שעשה אותם בדרך חכמה או שהשם הביא עליהם המכות ברשעת הגוים, כי אלו חפץ השם ביציאתם לא היה פרעה רודף אחריהם:
@16 **ואונקלוס** תרגם בכאן **ויצעקו** וצעיקו, עשאו ענין תרעומת, לומר שלא התפללו אבל היו מתרעמים לפניו על שהוציאם ממצרים, כלשון ויצעקו אל פרעה לאמר למה תעשה כה לעבדיך (לעיל ה טו). וכמוהו ותהי צעקת העם ונשיהם גדולה אל אחיהם היהודים (נחמיה ה א), מתרעמים עליהם בקול גדול וצעקה. **ובמכילתא** (כאן) תפשו להם אומנות אבותם, **ויאמרו אל משה המבלי אין קברים במצרים** , מאחר שנתנו שאור בעיסה באו להם אצל משה, אמרו לו **הלא זה הדבר אשר דברנו אליך** וגו'. ושאור שבעיסה הוא היצר הרע, והיה דעתם לומר כי מתחלה צעקו אל ה' לתת בלב פרעה לשוב מאחריהם, וכאשר ראו שלא היה חוזר אבל היה נוסע וקרב אליהם, אז אמרו לא נתקבלה תפלתנו ונכנסה בלבם מחשבה רעה להרהר אחרי משה כאשר בתחלה:
@19 **כי אשר ראיתם את מצרים היום לא תוסיפו לראותם עוד** . על דעת רבותינו היא מצות לא תעשה לדורות (מכילתא כאן). ואם כן יאמר הכתוב **אל תיראו** , **התיצבו** במקומכם **וראו את ישועת ה'** שיושיע אתכם היום מידם ואל תשובו לעבודתם, כי מצרים אשר ראיתם אותם היום הקב''ה מצוה אתכם עוד שלא תוסיפו ברצונכם לראותם מעתה ועד עולם. ותהיה מצוה מפי משה לישראל, ולא הוזכרה למעלה. וכן ולא ישיב את העם מצרימה למען הרבות סוס וה' אמר לכם לא תוסיפון לשוב בדרך הזה עוד (דברים יז טז), שהיא מצוה באמת, לא הבטחה:
@21 **מה תצעק אלי** . אמר ר''א כי משה כנגד כל ישראל, שהיו צועקים לו, כמו שאמר ויצעקו בני ישראל אל ה'. וא''כ למה אמר **מה תצעק אלי** , ראוי להם לצעק. ואולי יאמר מה תניחם לצעוק **דבר** להם **ויסעו** , כי כבר אמרתי לך ואכבדה בפרעה (פסוק ד). **ורבותינו** אמרו (מכילתא כאן) שהיה משה צועק ומתפלל, והוא הנכון, כי לא ידע מה יעשה, ואף על פי שאמר לו השם ואכבדה בפרעה, הוא לא היה יודע איך יתנהג, כי הוא על שפת הים והשונא רודף ומשיג, והיה מתפלל שיורנו ה' דרך יבחר. וזה טעם **מה תצעק אלי** , שהיית צריך לשאל מה תעשה ואין לך צורך לצעוק, כי כבר הודעתיך ואכבדה בפרעה, ולא סיפר הכתוב צעקת משה, כי הוא בכלל ישראל:
@25 **ויסע מלאך האלהים** . אמר ר''א **מלאך האלהים** הוא השר הגדול ההולך בענן, והוא הכתוב עליו וה' הולך לפניהם יומם. וכאשר נסע המלאך הזה **ההולך לפני מחנה ישראל וילך מאחריהם** נסע עמוד הענן עמו, **ויהי הענן והחשך** בין מחנה למחנה **ויאר** לישראל **את הלילה** בעמוד האש כאשר עשה בשאר הלילות לעבור הים, כי בלילה עברו. ועל דעתי זה שאמר הכתוב **ויסע מלאך האלהים** היה בתחלת הלילה, **ומלאך האלהים ההולך לפני מחנה ישראל** רמז לבית דינו של הקב''ה, שנקראת מדת הדין ''מלאך'' במקומות מן הכתוב, והוא השוכן בעמוד האש, והולך לפניהם לילה להאיר להם, ועל כן הזכיר **האלהים** . ויתכן שאינו נסמך, אבל הוא ביאור:
@25 **וראיתי** במכילתא דר' שמעון בן יוחאי שאל רבי יונתן בן יוחאי את ר' שמעון בן יוחאי מפני מה בכל כתוב ''מלאך ה''' וכאן ''מלאך האלהים'', אמר לו, אין אלהים בכל אלא דין וכו'. רמזו למה שאמרנו. **והנה** עתה נסע בעמוד האש מלפני מחנה ישראל והלך מאחריהם, ונסע עוד **עמוד הענן מפניהם ויעמוד מאחריהם** , והנה שני העמודים מאחריהם. ושב לבאר כי בא עמוד הענן הזה **בין מחנה מצרים ובין מחנה ישראל** , לומר שלא הפסיק עמוד הענן בין עמוד האש למחנה ישראל, אבל הפסיק בין מחנה מצרים ובין עמוד האש. **ויהי הענן והחשך** בין מחנה למחנה, והיה לישראל אור בעמוד האש אע''פ שהוא מאחריהם, מפני שהיה למעלה ולא היה עמוד הענן מפסיק אותו להם כאשר למצרים:
@25 **וזה** טעם **ויאר את הלילה** , כי האיר להם הלילה, אבל לא כשאר הלילות לנחותם בדרך, כי לא היה הולך לפניהם. והיה זה, שאלו היה עמוד האש הולך לפני ישראל כשאר הלילות, ועמוד הענן בין מצרים ובין ישראל, היו ישראל ממהרים ללכת, והמצרים לא יראו ולא יבאו אחריהם, ועתה הלכו ישראל לאטם ואין המרחק רב ביניהם, והיו המצרים רואים את מחנה ישראל מתוך הענן והולכים אחריהם, כי יראו האש מתוך הענן, אלא שלא היו יכולים ליקרב אליהם מפני הפסק שני העמודים. וזה טעם **ולא קרב זה אל זה כל הלילה** :
@25 **ויהי** באשמורת הבקר וישקף ה' אל מחנה וגו'. כי הסיר עמוד האש ממחנה ישראל כמנהג כל הימים, ושמו היום משקיף על מחנה מצרים, בינם ובין עמוד הענן אשר ישתמשו בו ישראל ביום. ויהם את מחנה מצרים בהשקיף עמוד האש עליהם, כי יגיע עליהם חומו הגדול ולהבה תלהט רשעים (תהלים קו יח). וכבר פירשתי במעשה בראשית (בראשית א ד) כי יסוד האש יקרא חשך, ו''הענן והחשך'' הוא עמוד אש וענן, אבל עמוד האש היה מאיר לכל ישראל בעמודו, והיה עתה מחשיך למצרים מפני היותו בא בעמוד הענן אשר יחשיך עליו כשמש אשר הענן יכסנו. והנה עשה הכל בשני עמודים הללו. וזהו הנכון בפסוקים האלה:
@27 **ויט משה את ידו על הים ויולך ה' את הים ברוח קדים וגו'** . היה הרצון לפניו יתברך לבקע הים ברוח קדים מיבשת שיראה כאלו הרוח היא המחרבת ים, כענין שכתוב (הושע יג טו) יבא קדים רוח ה' ויבוש מקורו וייחרב מעיינו, השגיא למצרים ויאבדם, כי בעבור זה חשבו אולי הרוח שם הים לחרבה, ולא יד ה' עשתה זאת בעבור ישראל, אע''פ שאין הרוח בוקעת הים לגזרים לא שמו לבם גם לזאת, ובאו אחריהם מרוב תאותם להרע להם, וזה טעם וחזקתי את לב פרעה ויבאו אחריהם, שחזק לבם לאמר ארדוף אויבי ואשיגם בים, ואין מידי מציל, ולא זכרו עתה כי ה' נלחם להם במצרים:
@34 **ויכסו את הרכב ואת הפרשים לכל חיל פרעה** . כך דרך מקראות לדבר כן בלמ''ד יתירה, כמו לכל כלי המשכן (להלן כז יט), לכל כליו תעשה נחשת (שם ג), ואינה אלא לשון תקון. לשון רש''י. ואינו כן במקום הזה, רק פירושו **ויכסו את הרכב ואת הפרשים** ולכל **חיל פרעה הבאים אחריהם בים** , והחיל אינם הרכב והפרשים, אבל הם עמו אשר לקח עמו, כמו שאמר למעלה (יד ט) כל סוס רכב פרעה ופרשיו וחילו. וכמוהו כסוי בלמ''ד כמים לים מכסים (ישעיה יא ט), ועשית מכסה לאהל (להלן כו יד), ובא ''על'' המכסה על הקרב (ויקרא ד ח), וכן רבים:
@37 **וירא ישראל את היד הגדולה** . את הגבורה הגדולה שעשתה ידו של הקב''ה, והרבה לשונות נופלים על לשון יד, וכלן לשון יד ממש הן, והמתקן יתקן הלשון אחר ענין הדבור. לשון רש''י. אבל אונקלוס לא פירש **היד הגדולה** גבורה, אבל אמר ית גבורת ידא רבתא. ור''א אמר המכה הגדולה, וכן הנה יד ה' הויה במקנך (לעיל ט ג), כבדה מאד יד האלהים שם (ש''א ה יא):
@37 **ועל** דרך האמת יאמר שנגלית להם **היד הגדולה** , והיא מדת הדין שעשה ה' במצרים, כי היתה שם במצרים מכה בהם, וזה כמו ועל הארץ הראך את אשו הגדולה (דברים ד לו), והוא הימין אשר תרעץ אויב, והיא זרוע ה' שאמר הכתוב עורי עורי לבשי עז זרוע ה' (ישעיה נא ט), הלא את היא המחרבת ים (שם י). ולא יתעלם ממך מה שאמר ''לבשי עז'' ממה שכתבנו בפסוק מידי אביר יעקב (בראשית מט כד):
@38 **אז ישיר משה** . לשון רבינו שלמה, כשראה הנס עלה בלבו שישיר שירה וכן עשה ויאמרו לאמר וגו'. וכן אז ידבר יהושע (יהושע י יב), כשראה הנס אמר לו לבו לדבר וכן עשה ויאמר לעיני ישראל, וכן שירת הבאר שפתח בה אז ישיר ישראל (במדבר כא יז) פירש אחריו עלי באר ענו לה, וכן ובית יעשה לבת פרעה (מ''א ז ח), חשב בלבו לעשות לה הבית. אז יבנה שלמה (שם יא ז), פירשוהו חכמי ישראל (סנהדרין צא:) שבקש לבנות ולא בנה. זהו לישב פשוטו. ומה יאמר הרב בפסוק יעשו עגל בחורב (תהלים קו יט), כמה ימרוהו במדבר יעציבוהו בישימון (שם עח מ), וכל המזמור כן, יהרג בברד גפנם (שם מז), ישלח בהם ערוב (שם מה), וכן ומאין יבאו אליך (מ''ב כ יד), מן המכים אשר יכוהו ארמים (שם ח כט, ט טו), וכן ומשה יקח את האהל (להלן לג ז), כי איננו לשון הוה, שלא לקחו אלא פעם אחת. **אבל** דרך הלשון הוא לומר עתיד במקום עבר, וכן יאמרו במקומות רבים ההפך. והטעם, כי מנהג הלשון שהמספר ענין יעמיד עצמו בזמן שיחפוץ, וירמוז למעשה ממנו. פעם יעמיד עצמו בזמן המעשה וידבר בו בענין הווה, ועומד עליו בתחלתו, ויאמר ''ישיר ישראל'' כאלו משוררים לפניו, וכן כלם, ופעם יאחר עצמו ויאמר זה נעשה כבר, והכל לאמת ענין, ולכן רוב שיבא זה יהיה בענין הנבואות:
@38 **כי גאה גאה** . על השירות, ועל כל מה שאקלס בו עוד יש בו נוספות. לשון רש''י. עשאו לשון רוממות וגודל. ואולי כן הוא, וכמוהו ופה ישית בגאון גליך (איוב לח יא), כי גאו המים (יחזקאל מז ה), ויגאה כשחל תצודני (איוב י טז), לשון גדל ורבוי. והנכון דעת אונקלוס, לשון גאות ממש, כי נתגאה על הסוס שמתגאה במלחמה ועל הגבור הרוכב בו, כי את שניהם רמה בים, וכן וברוב גאונך (פסוק ז), וכן כלם לשון גאות, כי המתגאה ירומם עצמו במעלה:
@39 **עזי וזמרת יה** . פירוש ר''א כי מלת עזי מושכת, **עזי וזמרת** עזי יה. והטעם, הודה כי עזו ותקפו אשר יזמר בו הוא השם, והוא היה ישועתי. **זה אלי ואנוהו** , אושיבנו בנוה, זה **אלהי אבי וארוממנהו** , שאספר גבורותיו. וזה הוא ודאי פשוטו של מקרא. אבל לא הזכיר השם שלם, והזכיר ממנו שתי אותיות בלבד, ודרך משה רבינו בכל התורה להזכיר השם הגדול כלו אשר אמר לו, זה שמי לעולם וזה זכרי לדור דור (לעיל ג טו). וכבר דרשו (תנחומא סוף פרשת תצא) בפסוק כי יד על כס יה (להלן יז טז), נשבע הקב''ה שאין הכסא שלם ואין השם מלא עד שימחה זרעו של עמלק:
@39 **ועל** דרך האמת, בעבור כי ישועת הים כולה היתה על יד מלאך האלהים, הוא שכתוב עליו כי שמי בקרבו (להלן כג כא), וכמו שאמר וירא ישראל את היד הגדולה (לעיל יד לא), כי ''היד'' ירמוז למדת הדין אשר היא היד הגדולה והנוקמת, והיא המקרעת הים, כמו שפירש הנביא עורי עורי לבשי עוז (ישעיה נא ט), הלא את היא המחרבת ים מי תהום רבה (שם י), וכמו שכתבתי למעלה (עי' לעיל יד לא), בעבור כן אמר כי עוזו וזמרתו השם הזה, כי ביה ה' צור עולמים (ישעיה כו ד). וכן ביאר מה לך הים כי תנוס (תהלים קיד ה), מלפני אלוה יעקב (שם ז). וכן אמרו במכילתא (בשלח ג) ירדו לים שכינה עמהם, שנאמר (לעיל יד יט) ויסע מלאך האלהים. ובאלה שמות רבה (ל א) אמר אין עוז אלא דין, שנאמר ועוז מלך משפט אהב (תהלים צט ד). **זה אלי ואנוהו** . ואעלה אותו אל נוה עליון. אלהי אבותי, שנראה להם באל שדי, ועתה ארומם אותו בשם השלם, כי מעתה יהיה **השם איש מלחמה** ויהיה ה' **שמו** , כטעם עתה ארומם עתה אנשא (ישעיה לג י). ויתכן שירמוז זה לשבע. ספירות בחכמה, כמו זה שמי לעולם וזה זכרי (לעיל ג טו). ובמכילתא (בשלח ג) **אלי** , עמי נהג במדת רחמים, ועם אבותי במדת הדין, ומנין שאין אלי אלא מדת רחמים, שנאמר אלי אלי למה עזבתני (תהלים כב ב), אל נא רפא נא. לה (במדבר יב יג), אל ה' ויאר לנו (תהלים קיח כז). ואם כן יאמר **זה אלי** , כי עמי הוא ''אל'' בזה, כי יתעלה עם הרחמים להיות רחמן בדינו:
@43 **ימינך ה' תרעץ אויב** . לשון רש''י, פשטו של דבר, ימינך הנאדר בכח מה מלאכתה, ימינך ה' תרעץ אויב, וכמה מקראות דוגמתו כי הנה אויביך ה' כי הנה אויביך יאבדו (תהלים צב י), עד מתי רשעים ה' עד מתי רשעים יעלוזו (שם צד ג), נשאו נהרות ה' נשאו נהרות קולם (שם צג ג). ורבים ככה. ואינו נכון לדעתי, כי הפסוקים יכפלו מלות לומר כי תמיד יהיה ככה מבלי שיבארו ענין רק בפעם השנית, ואלו אמר ימינך ה' ימינך ה' תרעץ אויב, היה כמות אלו הנזכרים:
@43 **ור''א** אמר כי פירושו **ימינך ה'** שאתה **נאדרי בכח ימינך ה' תרעץ אויב** , שהוא כמו אלה הנזכר. ויותר נכון לומר **ימינך ה'** הוא נאדר **בכח** להשפיל לכל גאה ורם, **ימינך ה' תרעץ אויב** בכח גדול. והזכיר ימין בלשון זכר ונקבה, כמו והנה יד שלוחה אלי והנה בו מגלת ספר (יחזקאל ב ט), והוא כפול כדרך הנבואות, **ודרך** האמת ידענה המשכיל מן הפסוקים הראשונים שפירשתי, וכך אמרו (שמו''ר כד א) היתה ידו אחת משקעתן וידו אחת מצלת אותם, כי הכח מציל, כענין שנאמר ועתה יגדל נא כח אדני (במדבר יד יז):
@46 **אמר אויב** . לעמו כשפתם בדברים. ארדפם ואשיגם ואחלק שלל עם שרי ועבדי. לשון רש''י. וראיתי במדרש חזית כך, תני רבי ישמעאל, **אמר אויב ארדוף אשיג** היה ראוי להיות תחלת השירה, ולמה לא נכתב, אלא שאין מוקדם ומאוחר בתורה (ראה קהלת רבה א יב). ואונקלוס סובר כן, ולכך תרגם דהוה אמר שנאה, על תחלת מחשבתו ברדפו אחריהם. **ולדעתי** בדרך הפשט הוא סדור בפסוק הראשון ממנו, כי מתחלה (בפסוק ד) אמר שטבעו בים וירדו במצולות, והיה זה כאשר שבו המים ויכסו את הרכב ואת הפרשים (בפסוק ה), ואח''כ (בפסוקים ח~י) שב לומר איך נעשה זה, כי ברוח אפך היא רוח קדים עזה נערמו מים מתחלה וקפאו התהומות, ומפני זה חשב האויב שירדוף וישיגם בים ויחלק שללם ותמלא נפשו מהם, ונשפת עליהם ברוחך וכסמו הים. והזכיר זה כי גם במחשבתו זאת סבה ופלא מאת השם שחזק לבם וסכל עצתם לבא בים, כאשר פירשתי למעלה (יד ד כא). על כן אמר אחריו מי כמוכה באלים, עושה גדולות ונפלאות בדבר והפכו:
@47 **נשפת ברוחך** . אמר ר''א מגזרת נשף, כי בנשף הביא רוח שהטביעה אותם. ורש''י פירש לשון הפחה, כמו וגם נשף בהם ויבשו (ישעיה מ כד). ויפה פירש. ודעתי עוד שענינו כמו בבי''ת, נשבת ברוחך, מלשון כי רוח ה', נשבה בו (ישעיה מ ז), ישב רוחו יזלו מים (תהלים קמז יח), כי שתי האותיות האלה ישמשו בענין אחד, כמו על גפי מרומי קרת (משלי ט ג), על גבי, אם בגפו (להלן כא ג), וכן ורכוש להם יבזור (דניאל יא כד), בזר עמים (תהלים סח לא), לשון פזור. וכן בשמות יחליפו אותם, שובך (ש''ב י טז), שופך (דהי''א יט טז):
@47 **ולרבותינו** במשנה (פאה פ''ו מ''א) הבקר לענים הבקר, כמו הפקר, ומן עבשו פרודות (יואל א יז) יאמר עפוש (פסחים מה:), ואמר בן פקועה (חולין סט.) במקום בן בקועה, מפני שנבקעה ומצאו שם בן תשעה חי. וכן על דעתי הכפישני באפר (איכה ג טז), הכבישני, מלשון ומלאו את הארץ וכבשוה (בראשית א כח), יכבוש עונותינו (מיכה ז יט). ובלשונם עוד מדה כפושה (יבמות קז:), כמו כבושה:
@47 **וענין** הכתוב, כי ברוחך הקשה והעזה נערמו מי הים, ונשפת ברוחך אשר אתה מנהג הים וכסמו ים. זהו וישב הים לפנות בקר לאיתנו (לעיל יד כז), כי שב לנשוב בו הרוח כאשר יעשה באיתנו בשוא גליו. וטעם **צללו כעופרת** , שבאו במצולות כמו העופרת. והזכיר **בזה** בשירה פעמים, כמו אבן (פסוק ה), כעופרת, כי גם זה להם מיד ה', שהיו בהם אנשים רבים יודעים לשחות והיו קרוב ליבשה, אף כי רוכבי הסוסים במים כלם היו ראוים להנצל כי הסוסים שטים הרבה על פני המים, וכן תופשי המגינים נצלים במים, ובכאן לא נמלט מהם אחד. וזהו טעם וינער ה' את מצרים (לעיל יד כז), שהיה השם מגביהם ברוחו הקשה ומשפילם בים, מלשון וינערו רשעים ממנה (איוב לח יג), והיה החסון לנעורת (ישעיה א לא), מה שמפיץ ומפיל מן הפשתן המתקן אותו:
@48 **מי כמכה באלים ה'** . בחזקים, כמו ואת אילי הארץ לקח (יחזקאל יז יג), אילותי לעזרתי חושה (תהלים כב כ). לשון רש''י. ובאמת שהלשון לשון תוקף וחוזק, אבל **מי כמכה באלים** במלאכי מעלה שהם נקראים אלים, מלשון זה אלי ואנוהו (פסוק ב). והקב''ה נקרא אל עליון על כלם, וכן ועל אל אלים ידבר נפלאות (דניאל יא לו), כמו הוא אלהי האלהים (דברים י יז), וכן הבו לה' בני אלים (תהלים כט א), כמו בני האלהים, כי יקראו אלים ובני אלים, וכן יקראו האלהים ובני אלהים, כי גדול ה' מכל האלהים (להלן יח יא), ויבאו בני האלהים להתיצב על ה', (איוב א ו). ויש אומרים (הרד''ק בספר המכלול י ב) כי ''בני'' איננו סמיכות, וכן בני שלשים (בראשית נ כג), אנשי מחקה על הקיר (יחזקאל כג יד). **וזה** טעם **מי כמכה נאדר בקדש** , שאין כמהו אדיר במעון הקדש בשמים. ובמכילתא (כאן) **מי כמוכה** באלו שהם משמשים לפניך במרום, שנאמר (תהלים פט ז ח) כי מי בשחק יערוך לה', ידמה לה', בבני אלים אל נערץ בסוד קדושים רבה:
@48 **נורא תהלות** . יראו מלהגיד תהלותיו פן ימעטו, כמו לך דומיה תהלה (תהלים סה ב). לשון רש''י. וגם ר''א פירש כי כל המהללים יראים להלל שמו, כי מי ישמיע כל תהלתו, והם חייבים להלל שמו כי הוא לבדו **עושה** , **פלא** . ולפי דעתי כי טעם **נורא תהלות** שהוא נורא בתהלות, כי יעשה דברים נוראים ומתהלל בהם, שעשה נקמות בעוברי רצונו והושיע בהם את עבדיו, והנה הוא בזה נורא ומהולל מאד. ובעבור כי מלכי ארץ נוראים בעשק ונלוז, אמר כי ה' הוא נורא בדברים אשר הוא מהולל בהם. וכן לך דומיה תהלה על דרך הפשט התוחלת לך תהלה, כי כל המיחלים לך יפיקו רצונם ויהללו שמך בציון וישלמו שם את נדרם אשר נדרו בעת צרתם, מלשון אך לאלהים דומי נפשי כי ממנו תקותי (תהלים סב ו), וידום השמש וירח עמד (יהושע יג י). וכן אך אל אלהים דומיה נפשי, מיחלת. כך נראה לי. ואחרים שמעתי אומרים, לך משתתקת התהלה כי לא תשיג תהלה לפעליך הגדולים והנוראים, מלשון ולילה ולא דומיה לי (תהלים כב ג), ויהיה טעם אלהים בציון (שם סה ב), האלהים אשר בציון, כלומר השוכן שם. והנכון מה שאמרנו:
@49 **נטית ימינך תבלעמו ארץ** . הטעם, כי אחר שנשפת ברוחך וכסמו הים **נטית** עליהם **ימינך** וזרועך **ותבלעמו ארץ** . והענין, כי אחר שטבעו השליכם הים כמנהג הימים, וכן אמר (לעיל יד ל) וירא ישראל את מצרים מת על שפת הים, ושם יכלו וישובו לעפר על הארץ כשהיו. והנה הם נבלעים ונשחתים, כמו יחד סביב ותבלעני (איוב י ח), בלע ה' ולא חמל (איכה ב ב), ודרך אורחותיך בלעו (ישעיה ג יב), השחיתו. **ורבותינו** אמרו (מכילתא כאן) שפתחה הארץ את פיה ובלעה אותם שזכו לקבורה בשכר שאמרו ה' הצדיק (לעיל ט כז), ואין לשון ''ימין ו''יד נטויה רק לנקמה ולהשחתה, ואולי יפרשו **נטית ימינך** להמיתם בים, **ותבלעמו הארץ** אחר כך, והיא הקבורה שזכו אליה:
@50 **נחית בחסדך עם זו גאלת נהלת בעזך** . אמר ר''א כי הוא עבר במקום עתיד כי כן יבא בנבואות. ועל דעתי כי יאמר נטית ימינך על האויב ותבלעם הארץ, **ונחית בחסדך** בעמוד הענן לנחותם הדרך **עם זו גאלת** , **ונהלת אותם** בעז ידיך **אל נוה קדשך** , כי אליו הולכים. וכן ונהרו אליו כל הגויים (ישעיה ב ב). ו''נוה קדשך'', הוא בית המקדש כאשר יאמר עוד, מקדש אדני כוננו ידיך (פסוק יז). וכן אמרו במכילתא (כאן) אין נוה אלא בית המקדש, שנאמר (ישעיה לג כ) חזה ציון קרית מועדנו עיניך תראנה ירושלם נוה שאנן:
@51 **שמעו עמים ירגזון** . יאמר, כאשר שמעו העמים ירגזון מתגרת ידיך, וחיל אחז יושבי פלשת בעת ששמעו. ויתכן שיאמר כי כבר שמעו העמים כל אשר עשה השם בארץ מצרים וירגזון תמיד מן המחלה אשר שם בהם, ויתפלל שתפול עליהם אימה ופחד שלא יצאו לקראת ישראל למלחמה. **ואמר** ר''א כי **תפול עליהם** שב אל פלשת אדום ומואב, לא אל כנען, וזהו שאמר **עד יעבור עמך ה'** , כי עליהם עברו טרם בואם אל ארץ כנען, ולא נלחמו עמהם. ואם יצא אדום לקראתו בעם כבד וביד חזקה (במדבר כ כ), לבל יעברו בארצו, לא נלחם בהם, ולולא כי נפל עליהם אימתה ופחד היו חפצים להלחם בם משנאתם אותם. ולא הזכיר עמון, כי עמון ומואב כגוי אחד הם. ויתכן שגם על הכנעני נפל פחדם ולא נלחם בהם עד עברם, כי הכנעני מלך ערד יושב הנגב (במדבר כא א) איננו כנעני ביחוסו, כדעת רבותינו (במד''ר ותנחומא שם):
@55 **ה' ימלוך לעולם ועד** . יאמר, כי הראה עתה כי הוא מלך ושלטון על הכל, שהושיע את עבדיו ואבד את מורדיו, כן יהי הרצון מלפניו לעשות בכל הדורות לעולם, לא יגרע מצדיק עיניו, ולא יעלימהו מן הרשעים המריעים. ובאו כזה פסוקים רבים, כגון ימלוך ה' לעולם אלהיך ציון לדור ודור הללויה (תהלים קמו י), יהי שם ה' מברך מעתה ועד עולם (שם קיג ב), והיה ה' למלך על כל הארץ (זכריה יד ט). **ואונקלוס** נתיירא ממנו בעבור שהמלכות לאלהים היא לעולמי עד, ולפיכך עשאו לשון הוה ה' מלכותיה קאים לעלם ולעלמי עלמיא, כדרך מלכותך מלכות כל עולמים (תהלים קמה יג). ולא הבינותי דעתו בזה, שהרי כתוב יהי כבוד ה' לעולם (שם קד לא), וימלא כבודו את כל הארץ (שם עב יט), יתגדל ויתקדש, יאמן ויגדל שמך (דהי''א יז כד). ויתכן שטעמם כסוד הברכות:
@56 **כי בא סוס פרעה ברכבו ובפרשיו** . אמר ר''א שגם זה מן השירה, כי היו משוררים ואומרים **כי בא סוס פרעה ברכבו ובפרשיו בים וישב עליהם את מי הים** בעוד **בני ישראל הולכים ביבשה בתוך הים** , והוא נס בתוך נס. ואיננו בלשון השירה והנבואות. אבל פירושו, אז ישיר משה, כי בא סוס פרעה ביום ההוא מיד, לא מיום המחרת או אחרי כן. או טעמו אז ישיר, כאשר בא סוס פרעה בים והשיב עליהם ה' מי הים בעוד בני ישראל הולכים ביבשה בתוכו, להגיד כי בלכתם בתוכו ביבשה אמרו השירה. ואמר עוד, כי אז לקחה מרים הנביאה את התוף בידה וענתה להם הפסוק הראשון של השירה שתענינה כן אחרי משה וישראל:
@57 **אחות אהרן** . הנכון בעיני כי מפני שהוזכרו בשירה משה ומרים ולא הוזכר אהרן רצה הכתוב להזכירו, ואמר **אחות אהרן** דרך כבוד לו, שהוא אחיה הגדול ואחותו הנביאה מתיחסת אליו, שגם הוא נביא וקדוש ה'. ויתכן שדרך הכתובים ליחס אל גדול האחים, וכן ובני כלב אחי ירחמאל (דהי''א ב מב), שהיה גדול מאחיו, שנאמר (שם ב ט) את ירחמאל ואת רם ואת כלובי:
@62 **שם שם לו חק ומשפט ושם נסהו** . במרה נתן להם מקצת פרשיות של תורה שיתעסקו בהם, שבת פרה אדומה ודינין. **ושם נסהו** , לעם, לשון רש''י. והיא דעת רבותינו (סנהדרין נו:). ואני תמה, למה לא פירש כאן החקים האלה והמשפטים ויאמר ''וידבר ה' אל משה צו את בני ישראל'' כאשר אמר בפרשיות הנזכרות למעלה דברו אל כל עדת בני ישראל וגו' (לעיל יב יג), וכן יעשה בכל המצות באהל מועד, בערבות מואב, ופסח מדבר (במדבר ט ב). **ולשון** רש''י שאמר פרשיות שיתעסקו בהם, משמע שהודיעם החקים ההם ולימד אותם עתיד הקב''ה לצוות אתכם בכך, על הדרך שלמד אברהם אבינו את התורה, והיה זה להרגילם במצות ולדעת אם יקבלו אותם בשמחה ובטוב לבב, והוא הנסיון שאמר **ושם נסהו** , והודיעם שעוד יצוום במצות, זהו שאמר **אם שמוע תשמע לקול ה' אלהיך והאזנת למצותיו** אשר יצוה אותך בהם:
@62 **ועל** דרך הפשט, כאשר החלו לבא במדבר הגדול והנורא וצמאון אשר אין מים שם להם במחייתם וצרכיהם מנהגים אשר ינהגו בהם עד בואם אל ארץ נושבת, כי המנהג יקרא **חק** , כענין הטריפני לחם חקי (משלי ל ח), חקות שמים וארץ (ירמיה לג כה), ויקרא **משפט** בהיותו משוער כהוגן, וכן כה עשה דוד וכה משפטו כל הימים (ש''א כז יא), כמשפט הראשון אשר היית משקהו (בראשית מ יג), וארמון על משפטו ישב (ירמיה ל יח), על מדתו. או שייסרם בחקי המדבר, לסבול הרעב והצמא, לקרוא בהם אל ה', לא דרך תלונה. ומשפטים, שיחיו בהם, לאהוב איש את רעהו, ולהתנהג בעצת הזקנים, והצנע לכת באהליהם בענין הנשים והילדים, ושינהגו שלום עם הבאים במחנה למכור להם דבר, ותוכחות מוסר שלא יהיו כמחנות השוללים אשר יעשו כל תועבה ולא יתבוששו, וכענין שצוה בתורה (דברים כג י) כי תצא מחנה על אויביך ונשמרת מכל דבר רע:
@62 **וכן** ביהושע נאמר ויכרות יהושע ברית לעם ביום ההוא וישם לו חק ומשפט בשכם (יהושע כד כה), אינם חקי התורה והמשפטים, אבל הנהגות ויישוב המדינות, כגון תנאים שהתנה יהושע שהזכירו חכמים (ב''ק פ:), וכיוצא בהם. ואמר **ושם נסהו** , להודיע כי אשר הוליכם בדרך הזה שאין שם מים והביאם אל המים המרים, לנסיון, כמו שאמר ויענך וירעיבך ולמען נסותך להטיבך באחריתך (דברים ח טז):
@62 וטעם **ויורהו ה' עץ** . שהראה אותו עץ ואמר לו השלך את העץ הזה אל המים וימתקו. ובעבור שלא מצאתי לשון מורה אלא בענין למוד, ויורני ויאמר לי (משלי ד ד) למדני, וכן כלם, נראה בדרך הפשט כי העץ ההוא ימתיק המים בטבעו, והוא סגולה בו, ולימד אותה למשה. **ורבותינו** אמרו (מכילתא ותנחומא כאן) שהיה העץ מר והוא נס בתוך נס, כענין המלח שנתן אלישע במים (מ''ב ב כא). ואם כן אמר **ויורהו** כי לא היה העץ נמצא במקום ההוא, והקב''ה הורהו את מקומו. או שהמציאהו אליו בנס. ושוב מצאתי בילמדנו (מדרש תנחומא כאן) ראה מה כתיב שם, **ויורהו ה' עץ** , ויראהו לא נאמר אלא **ויורהו** , הורהו דרכו. כלומר שהורהו ולמדהו דרכו של הקב''ה שהוא ממתיק המר במר:
@63 **אם שמוע תשמע לקול ה' אלהיך** . פירש ר''א להבין טעם מה שיצוך לעשות. **והישר בעיניו תעשה** , מצות עשה. **והאזנת למצותיו** , מצות לא תעשה. ובמכילתא (כאן) אמרו **והישר בעיניו תעשה** , זה משא ומתן, מלמד שכל הנושא ונותן באמונה ורוח הבריות נוחה הימנו מעלה עליו כאלו קיים כל התורה כלה. ועוד אבאר זה בהגיעי בפסוק ועשית הישר והטוב (דברים ו יח), אם ייטב עמי האל הטוב:
@63 **כל המחלה אשר שמתי במצרים לא אשים עליך** . לשון רש''י לא אשים עליך, ואם אשים הרי הם כאלו לא הושמו כי אני ה' רופאך. זה מדרשו. ופשוטו, כאדם שאומר אני הוא הרופא המזהירך שלא לאכול דברים המחזירים את האדם לחליו, ע''כ. ואין פשוטו של מקרא שיהיה **רופאך** תואר, ואין דרך שיבטיח האדון את עבדיו אם תעשה כל רצוני וחפצי לא אמית אותך בתחלואים רעים. ולא כן כל ההבטחות שבתורה. **אבל** זו אזהרה, שיזהירם שלא יהיו במורדיו כמצרים, כי בשמעם קולו ינצלו מכל אותה המחלה, כי כל המחלה ההיא ראויה לבא על כל עוברי רצונו כאשר באה על המצרים שלא שמעו אליו. וזו כדרך שאמר שישים בך את כל מדוה מצרים אשר יגורת מפניהם ודבקו בך (דברים כח ס). ואמר **כי אני ה' רופאך** , הבטחה, שאסיר מקרבך מחלה באה כדרך כל הארץ כאשר רפאתי המים:
@63 **ואמר** ר''א כי האות הזה, והוא הראשון במדבר, הפך המכה הראשונה שבמצרים, כי מימי היאור היו מתוקים והפכם לרעה, ואלו היו מרים ורפא אותם, והנה השם יעשה דבר והפכו, על כן יש לך לירא מפניו שלא תמר בו שלא יריע לך כהם, ולאהוב אותו כי ייטב לך כאשר ריפא לכם המים:
@63 **וענין** הכתוב שמדבר בשני לשונות, למצותיו וחקיו, ולא אשים עליך כי אני ה', כבר כתבתי לך שלישים בביאור ענינו. ויובן ממלת **לקול** וממלת **אני** , כי אם נשמע לקול אלהינו לשמור מצות ה' וחקיו יהיה השם הנכבד רופאנו. ומכאן תקנו בברכות אשר קדשנו במצותיו וצונו, כי הברכות יש בה מלכות, והמצות נצטוו לנו מן העולם ועד העולם. והמשכיל יבין. והנני מאיר עיניך כי כל ברכה שיש בה מלכות היא כן, שחלקו כבוד למלכות העולם אשר קדשנו ואשר עשה לנו, והסמוכה לחברתה אשר לא יזכירו בה מלכות הן לנכח, אתה גבור, אתה קדוש, וכן כלם. ותקנו בעלינו לשבח נסתר מפני שמזכירין בה מלפני מלך מלכי המלכים. והבן זה:
@64 **ושם שתים עשרה עינות מים ושבעים תמרים** . איננו דבר גדול בהמצא במקום שבעים תמרים, כי בשפל מקומות ימצאו אלף תמרים ויותר מהמה, ועינות מים רבים יוצאים בבקעה ובהר, ולא יספר הכתוב זה. ור''א אמר כי יספר הכתוב שבאו במקום טוב, הפך מרה, כי באלים עינות רבות והם מים מתוקים ויפים, כי התמרים לא יצליחו בארץ שמימיה מרים, ולכן אמר **ויחנו שם** , כי נתעכבו שם בעבור זה ימים יותר משאר המקומות שעברו בהן. אבל בפרשת אלה מסעי לא ספר דבר מי מרה, ואמר ויסעו ממרה ויבאו אלימה ושם שתים עשרה עינות מים ושבעים תמרים ויחנו שם (במדבר לג ט). ולא האריך כן בכל מקומות המסעים:
@64 **ורש''י** כתב **שתים עשרה עינות מים** כנגד שנים עשר שבטים נזדמנו להם, **ושבעים תמרים** כנגד שבעים זקנים. לא ידעתי מהו הזמון הזה, אם במעשה הנסים נעשו שם באותה שעה. אבל ראיתי במכילתא (כאן) ר' אלעזר המודעי אמר, מיום שברא הקב''ה את עולמו ברא שם שתים עשרה מבועין כנגד י''ב שבטי ישראל, ושבעים דקלים כנגד שבעים זקנים. וספר הכתוב זה כי חנו עליהם כל שבט על מבועו, והזקנים ישבו בצלם לשבח האל עליהם שהכין להם כן בארץ ציה. ועוד לרבותינו במדרש של ר' נחוניא בן הקנה בכתוב הזה פירוש נפלא בעינינו:
@65 **ויסעו מאלים ויבאו וגו' אל מדבר סין** . אחז הכתוב דרך קצרה, כי בנסעם מאילים חנו על ים סוף, ויסעו מים סוף ויחנו במדבר סין (במדבר לג י יא), כי המדבר הזה גדול, מגיע מאלים ועד סיני, וכאשר נסעו מאלים חנו על ים סוף במדבר ההוא, ונסעו משפת הים ונכנסו בתוך המדבר ועשו בו מסעות דפקה ואלוש (שם יב יג), ויסעו מאלוש אשר הוא במדבר סיני ויחנו ברפידים (שם יד). ועל דעת רבותינו (שמו''ר כה ה) היה דבר המן באלוש, כי בראותם שהיו חונים ונוסעים וחונים במדבר בדפקה ואלוש ולא יצאו ממנו פחדו ונתרעמו, וזה טעם וילונו במדבר, כי לא היתה תלונה ביום בואם שם רק בהיותם במדבר:
@65 וטעם **אשר בין אלים ובין סיני** . להפריש בין מדבר סין זה למדבר צין האחר (במדבר כ א) הכתוב בצד''י שבאו שם בשנת הארבעים, ותמת שם מרים, ולכך הזכיר שם ויחנו שם במדבר צין היא קדש (שם לג לו), להפרישו מזה:
@66 **וילונו כל עדת בני ישראל על משה** . היה ראוי שיספר הכתוב תחלת טענת התלונה כאשר אמר במרה (לעיל טו כד) וברפידים (להלן יז ב) ובכל התלונות, ויאמר כאן ואין בשר לאכול ואין לחם לשבוע וירעב העם ללחם.
@66 ורש''י כתב שאמר הכתוב **בחמשה עשר יום לחדש השני** להפריש חנייה זו לפי שבו ביום נשלמה החררה שהוציאו ממצרים והוצרכו למן, ללמדך שאכלו משיירי הבצק ס''א סעודות. וקבלת רבותינו היא (מכילתא כאן). ולזה לא פירש תלונותם מפני שלא האריך בנס הזה הנעשה להם בסתר, וכבר כתבתי הטעם בסדר ויגש אליו (בראשית מו טו). ור''א אמר כי הזכיר הכתוב **בחמשה עשר יום לחדש השני** לאמר שכבר יש להם חדש ימים שיצאו ממצרים ואכלו הלחם אשר הוציאו ממצרים ומקניהם כי קהל רב היו, וזה טעם התלונה:
@66 **ועל** דעתי הזכיר הכתוב **ויבאו אל מדבר סין** להודיע תלונתם, כי בבואם אל מדבר סין וכבר רחקו ממצרים אמרו מה נאכל ומה יספיק לנו במדבר הגדול אשר אנחנו באים בו. או כי מתחלה היו סבורים שיבאו אל הערים אשר סביבותיהם אחרי ימים מעטים, ועתה יש להם חדש ועיר מושב לא מצאו, ואמרו כלנו מתים במדבר הגדול שבאנו בו. וזה טעם **וילונו על משה ועל אהרן במדבר** , כי תלונתם מפני המדבר. וכן אמרו (בפסוק הבא) **כי הוצאתם אותנו אל המדבר הזה להמית את כל הקהל הזה ברעב** , הזכירו המדבר והקהל לאמר כי קהל גדול כזה ימות בלי ספק ברעב במדבר הגדול הזה, והקב''ה שמע אליהם, והחל עתה לערוך להם שולחן במדבר עד בואם אל ארץ נושבת:
@68 **הנני ממטיר לכם** . אמר ר''א כי בעבור היותו יורד כדמות מטר מן השמים יקרא ממטיר, ומצינו ימטר על רשעים פחים אש וגפרית (תהלים יא ו), וה' המטיר על סדום ועל עמורה גפרית ואש (בראשית יט כד). ואולי היו באים עם המטר. ודעת אונקלוס שהוא לשון ירידה, הא אנא מחית:
@68 **ויתכן** שיהיה מענין כמטרא לחץ (איכה ג יב), אע''פ שהוא שרש אחר, כי בכל זריקה אשר תבא מלמעלה יאמרו כן, ותקרא ''מטרה'' על שם שימטיר עליה החצים. ואמרו (תהלים עח כז) וימטר עליהם כעפר שאר וכחול ימים עוף כנף. או שיאמר כן בעוף השמים כי ירד עליהם כמטר:
@68 **לחם** . בעבור שיעשו ממנו לחם כמו שכתוב (במדבר יא ח) ועשו אותו עוגות, כי כל פת יקרא לחם, לא בהיותו מן החטה או מן השעורים בלבד. ואמר **ממטיר לחם** , כי להיותו לחם ימטירנו להם, וכן ארץ ממנה יצא לחם (איוב כח ה), וכן להוציא לחם מן הארץ (תהלים קד יד), שיוציא החטה שיעשו ממנה לחם. ויש אומרים (הראב''ע וכן הרד''ק כאן ובספר השרשים שרש לחם) **הנני ממטיר לכם לחם** , מאכל, וכן לחם אשה (ויקרא ג טז), כי את לחם אלהיך הוא מקריב (שם כא ז), כי תשב ללחום את מושל (משלי כג א), כלם ענין מאכל. והנכון כי ללחום (שם), לאכול לחם, ולחם אלהיך (ויקרא כא ז~ח), כנוי, שהוא סעודה לאלהיך כלחם לאדם, כי מצאנו לא על הלחם לבדו יחיה האדם (דברים ח ג):
@68 **למען אנסנו הילך בתורתי** . אם ישמרו מצות התלויות בו שלא יותירו ממנו ולא יצאו בשבת ללקוט. לשון רש''י. ואיננו נכון, אבל הוא כמו שאמר (שם טז) המאכילך מן במדבר אשר לא ידעון אבותיך למען ענותך ולמען נסותך להטיבך באחריתך, כי נסיון הוא להם שלא היה בידם מזון, ולא יראו להם עצה במדבר רק המן, שלא ידעו מתחלה, ולא שמעו מאבותם, ויורד להם דבר יום ביומו וירעיבו אליו, ועם כל זה שמעו ללכת אחרי השם לא לחם:
@68 **וככה** אמר להם עוד (שם ח ב) וזכרת את כל הדרך אשר הוליכך ה' אלהיך זה ארבעים שנה במדבר למען ענותך ולמען נסותך לדעת את אשר בלבבך התשמור מצותיו אם לא, כי היה יכול להוליכם בדרך הערים אשר סביבותיהם והוליכם במדבר נחש שרף ועקרב (שם טו), ושלא יהיה להם לחם רק מן השמים דבר יום ביומו, לנסותם ולהטיב להם באחרונה, שיאמינו בו לעולם. וכבר פירשתי ענין הנסיון בפסוק והאלהים נסה את אברהם (בראשית כב א). והרב אמר במורה נבוכים (ג כד) לדעת כל יודע ולנסות היש תועלת בעבודת האל ואם יש בה ספוק צורך אם לא. ואם כן היה ראוי שיאמר ''למען ינסה לדעת'':
@68 **והנה** לא הזכיר כאן דבר רק המן שהוא הלחם שהמטיר להם, אבל כאשר אמר להם משה (בפסוק ח) **בתת ה' לכם בערב בשר לאכול ולחם בבקר לשבוע** , ידענו כי הכל נאמר לו, אבל הכתוב יקצר בדברים הנכפלים בענין הצווי או בספור, כאשר הזכרתי לך פעמים רבים (לעיל ט יב, י יב, יא א). ופעמים לא יזכיר האחד כלל, דכתיב בפרשה הזאת (פסוק לב) **זה הדבר אשר צוה ה' מלא העומר ממנו** , ולא נכתבה הצואה כלל, וכן במקומות רבים:
@68 **ועל** דעת האומרים (הראב''ע) כי ''לחם'' כל מאכל, יתכן שיאמר **הנני ממטיר** ' **לכם לחם** על המן ועל השלו, כי יתכן להם שאלתם ששאלו לחם ובשר, ומשה פירש שיהיה **הבשר בערב לאכול והלחם בבקר לשבוע** כדרך כל הארץ:
@70 **ערב וידעתם כי ה' הוציא אתכם מארץ מצרים** . ולא אנחנו המוציאים אתכם משם כאשר אמרתם **כי הוצאתם אותנו** (לעיל פסוק ג). **ובקר וראיתם את כבוד ה'** . לא נאמר זה על הכבוד הנראה בענן, כי בו ביום היה כדבר להם אהרן ויפנו אל המדבר (בפסוק י). ופירש רש''י, אלא כך אמר להם, **ערב וידעתם** כי היכולת בידו ליתן תאותכם ובשר יתן לכם, אך לא בפנים מאירות יתננה לכם, כי לא כהוגן שאלתם אותה ומכרס מלאה, והלחם ששאלתם לצורך כהוגן, בירידתו תראו לבקר את כבוד פניו שיורידנו לכם דרך חיבה בבקר שיש שהות להכינו. ואינו נכון שיאמר **ובקר וראיתם את כבוד ה'** מפני שיקדים להם מתנת המן בבקר, כי מה כבוד ה' בזה, ועוד שסמך לזה **בשמעו את תלונותיכם** :
@70 **והמדרש** הזה לרבותינו איננו בפירוש **וראיתם את כבוד ה'** , אבל אמרו כן מפני שחלק להם הפרנסה בשני עתים מן היום ולא נתן הכל בבקר. וכך אמרו במכילתא (כאן) ויאמר משה בתת ה' לכם בערב, מכאן אתה למד שבפנים חשוכות נתן להם השלו, והמן ששאלו כהלכה נתן להם בפנים מאירות, כלומר בבקר:
@70 **ורבי** אברהם אמר ''ובקר'' נמשך בפסוק הראשון. כי בעבור שאמרו **כי הוצאתם אותנו משם** אמר שני אותות יעשה השם לכם שתדעו כי הוא הוציא אתכם משם, האחד בערב היום הזה והשני למחר בבקר. והיה ראוי שיאמר **ערב ובקר וראיתם כי ה' הוציא אתכם** , שאין **ובקר** דבק עם **וראיתם את כבוד ה'** , כי ביום עצמו ראו הכבוד. וגם זה איננו נראה כן:
@70 **והנכון** בעיני כי היה הפלא במן גדול מאד. כי השלו הגיז אותו מן הים ברוח נסע מאתו כדרך העולם, אבל המן נוצר להם עתה יצירה חדשה בשמים כענין מעשה בראשית, והוא מה שאמרו בו (אבות ה ו) שנברא בין השמשות:
@70 **ולכן** אמר הכתוב באות אשר יעשה לכם היום בערב תדעו כי הוא הוציא אתכם מארץ מצרים, כי יערוך לכם שולחן במדבר, אבל בפלא הגדול אשר יעשה לכם בבקר תראו את כבוד מלכותו אשר מי אל בשמים ובארץ אשר יעשה כמעשיו וכגבורותיו, שבגדולות ובנפלאות שיעשה השם יראה את כבודו, כענין לקבץ את כל הגוים והלשונות ובאו וראו את כבודי (ישעיה סו יח). וכתיב (שם יט) והגידו את כבודי, וכן רבים. וכן הוא דעת אונקלוס שאמר ותחזון ית יקרא דה', ולא תירגם בו ''ואיתגלי'':
@70 **ודע** כי יש במן ענין גדול, רמזוהו רבותינו במסכת יומא (עה:) לחם אבירים אכל איש (תהלים עח כה), לחם שמלאכי השרת אוכלין, דברי ר' עקיבא. אמר לו ר' ישמעאל טעית, וכי מלאכי השרת אוכלין לחם, והלא כבר נאמר (דברים ט ט) לחם לא אכלתי ומים לא שתיתי, אלא לחם אבירים, לחם שנבלע באיברים. והענין הזה שאמר רבי עקיבא הוא, שקיום מלאכי השרת בזיו השכינה, וכן דרשו (שמו''ר לב ד) ואתה מחיה את כלם (נחמיה ט ו), מחיה לכלם. ועליו נאמר (קהלת יא ז) ומתוק האור, שישיגו בו באור טוב טעם. והמן הוא מתולדת האור העליון שנתגשם ברצון בוראו יתברך (זוהר בלק ר''ח.), ונמצא שאנשי המן ומלאכי השרת נזונין מדבר אחד. ור' ישמעאל תפשו מפני שקיומם אינו בדבר המתגשם מתולדת האור שהרי קיומם באור העליון עצמו, ומפני זה היו מוצאים טעם במן מכל מה שירצו, כי הנפש במחשבתה תדבק בעליונים ותמצא מנוח חיים ותפק רצון מלפניו (ע''פ משלי ח לה):
@70 **ואמרו** במכילתא (להלן פסוק כה) היום אין אתם מוצאים אותו אבל אתם מוצאים אותו לעולם הבא. וזה יסבול שני פירושים, שנאמר שיהיה בבני העולם הבא מי שלא הגיעה מעלתם ליהנות תמיד מזיו השכינה, ויהיה קיומם בדבר המתגשם מן הזיו ההוא, כמעלת דור המדבר שהשיגו לזיו השכינה בים, כמו שאמרו (במכילתא לעיל טו ב) ראתה שפחה על הים מה שלא ראה יחזקאל הנביא, ומאותה שעה נתעלית נפשם להתקיים בתולדותיו שהוא המן:
@70 **ויותר** נכון שרמז הכתוב לדברי ר' אלעזר בן חסמא במלת היום שבני העולם הבא יהיה קיומם ביסוד המן שהוא הזיו העליון, כמו שאמרו (ברכות יז.) אין בו לא אכילה ולא שתיה אלא צדיקים יושבים ועטרותיהם בראשיהם והן נהנין מזיו השכינה. ובני העולם הבא יתקיימו בהנאתן מזיו השכינה בהדבקם בו בעטרה שבראשם. והעטרה היא המדה הנקראת כן שאמר בה הכתוב (ישעיה כח ה) יהיה ה' צבאות לעטרת צבי, ובה נאמר (שה''ש ג יא) בעטרה שעטרה לו אמו. ורמזו על קיום בני העולם הבא, ורמזו על עיקר המן:
@70 **ואמר** הכתוב (תהלים עח כג~כה) ויצו שחקים ממעל ודלתי שמים פתח, וימטר עליהם מן לאכול ודגן שמים נתן למו, לחם אבירים אכל איש, וכן אמר (שם קה מ) ולחם שמים ישביעם שנראה מזה שיהיה הדגן הזה בשמים והורידו להם בפתיחת דלתיו, והוא מה שפירשתי שנתגשם האור, כי באור העליון יאמר הכתוב כלשון הזה נפתחו השמים ואראה מראות אלהים (יחזקאל א א). או שכבר היה בשמים, כמאמרם (אבות ה ו) שנברא בין השמשות:
@71 **ונחנו מה כי תלינו** . אמר רבי אברהם ונחנו מה בידינו לעשות, כי לא עשינו רק מה שצונו. ואיננו כן, אבל הוא כמו מה אנוש כי תזכרנו (תהלים ח ה), מה אדם ותדעהו (שם קמד ג), כי במה נחשב הוא (ישעיה ב כב). וזאת דרך ענוה, כי מה אנחנו שתליתם עלינו שהוצאנו אתכם מארץ מצרים, הן אנחנו אין ופעלינו הבל, ולא **עלינו תלונותיכם כי על ה'** , הוא המוציא אתכם מארץ מצרים לא אנחנו. ובמכילתא (כאן) וכי מה אנחנו ספונים שאתם עומדים ומתרעמים עלינו:
@72 **בתת ה' לכם בערב בשר** . יפרש מאמרו הראשון, **כי בתת ה' לכם בערב בשר לאכול וידעתם כי ה' הוציא אתכם מארץ מצרים** , ובתתו לכם **לחם בבקר לשבוע וראיתם את כבוד ה'** :
@76 **שמעתי את תלונות בני ישראל דבר אליהם לאמר בין הערבים** . זה הדבור כבר אמרו משה לישראל (בפסוק ח), אבל נשנה בעבור שאמר **שמעתי את תלונות בני ישראל** , כי מתחלה אמר (בפסוק ד) **הנני ממטיר לכם לחם** , כעושה עמהם חסד ברצונו או לזכותם, ועתה הגיד כי נחשב להם לעון, ובעבור התלונה יעשה עמהם כן כדי שידעו בו כי אני ה' אלהיכם, כי עד עתה אינכם מאמינים בה' אלהיכם, על כן אתם מתלוננים על נביאיו:
@76 **ויתכן** שמתחלה לא הבטיחם להיות להם המן כל ימי המדבר, והיו חושבים אולי יהיה ליום אחד או לשנים בהיותם במקום ההוא, ובנסעם משם יבאו אל לחם, ועתה אמר להם **בין הערבים תאכלו בשר** תמיד ובכל בקר **ישבעו לחם** כל ימי המדבר:
@76 **וכן** דעת רבותינו שהיה השלו עמהם מן היום ההוא והלאה כמו המן, וכן נראה, כי על שני הדברים נתלוננו ובשניהם שמע את תלונתם ותאותם יביא להם, כי מה יתן להם ומה יוסיף להם בשר ליום אחד או לשנים, והפרשה שתפרש ותאריך בענין המן, כי כל מעשיו הם נפלאים, ותקצר בענין השלו, **ויהי בערב ותעל השלו** (פרק יג), כי הוא בנוהג שבעולם:
@76 **וענין** השלו השני בקברות התאוה (במדבר יא לא), כי לא בא להם ממנו עתה לשובע כאשר יאמר בכאן תמיד (בפסוקים ח יב) **בשר לאכול ולחם לשבוע** . ויתכן שהיו גדוליהם לוקטין אותו, או שהיה מזדמן לחסידים שבהם, וצעיריהם היו תאבים לו ורעבים ממנו, כי לא יספר **בשלו וילקטו המרבה והממעיט** כאשר אמר במן, ולכך אמר שם (במדבר יא ד) **והאספסוף אשר בקרבו התאוו תאוה** , ואמר (שם) **וישובו ויבכו גם בני ישראל** , שהיו גם מהם בוכים לו ולא כלם, ואז נתן להם ממנו לרוב מאד, כאשר אמר (שם לב) הממעיט אסף עשרה חמרים, ואכלו חדש ימים בשפע ההוא ושב לענינו הראשון. ועל דרך הפשט היו כל מעשה השלו לעתים, והמן שהיה חיותם היה להם תמיד, כי עיקר תלונתם עליו כדכתיב **כי הוצאתם אותנו אל המדבר הזה להמית את כל הקהל הזה ברעב** :
@78 **דק מחספס** . על דעת אונקלוס מן מחשוף הלבן (בראשית ל לז), חשף ה' (ישעיה נב י), בחלוף השי''ן בסמ''ך, ועין הפועל כפולה:
@78 **דק ככפור** . הוא הנופל בימי הקור, וכן כפור כאפר יפזר (תהלים קמז טז). ותרגום אונקלוס דעדק כגיר כגלידא על ארעא. וכתב רש''י ז''ל כאבני גיר, והוא מין צבע שחור, כדאמרינן גבי כסוי הדם (חולין פח:) הגיר והזרניך. דעדק כגיר דגלידא על ארעא, דק היה כגיר ושוכב מוגלד כקרח על הארץ. וכן פירושו, **דק ככפור** , שטוח וקלוש ומחובר כגליד, דק, שהיה מגליד גלד דק מלמעלה. ומה שתרגם אונקלוס תוספת הוא על לשון העברית, ואין לו תיבה בפסוק:
@78 **ואין** כל זה נכון, כי הגיר הוא העפר הלבן הנדבק לאבנים וינפצו אותו וטחין בו הכותלים בסיד, והוא לבן מאד, וטוב מן הסיד לטוח על הקירות, וכן כתוב (דניאל ה ה) על גירא די כתל היכלא, ועל כן ייחס בו המן, שהוא לבן ומפוזר על הארץ כגיר המנופץ:
@78 **ואונקלוס** תרגם במלת כפור בשני פנים, עשאו תחלה מן וכפרת אותו מבית ומחוץ בכופר (בראשית ו יד), ולכן אמר כגיר, שבו טחין ומכסים, ועשאו עוד מן כפור כאפר יפזר (תהלים קמז טז), שהוא הקרח הדק היורד בקור, כמו שתרגם וקרח בלילה (בראשית לא מ) וגלידא נחית עלי בליליא, וממנו מינים, והאחד יקרא גליד, כמו ששנינו במשנה מקואות (ז א) אלו מעלין ולא פוסלין השלג והברד והכפור והגליד. וכן יתרגם אונקלוס בשני פנים בכתובים רבים:
@78 **אבל** בנוסחאות הבדוקות מן התרגום כתוב בהן דעדק דגיר כגלידא על ארעא, ופירושו עשוי חמרים חמרים כגליד על ארעא, והוא האמת, שאם היה מלשון גיר היה מתורגם כגירא דגלידא, כי כן דרך הלשון ההוא:
@84 **וירם תולעים ויבאש** . הרי זה מקרא הפוך, שבתחלה הבאיש ולבסוף התליע, כענין שנאמר (בפסוק כד) ולא הבאיש ורמה לא היתה בו. וכן הוא הדרך לכל דבר שהוא מן המתליעים. לשון רש''י. ואלו היה המן מתליע בדרך הטבע כדרך שאר המתליעים, היה הדבר כן, אבל זה שהתליע בדרך נס יתכן שהרים תולעים תחלה, ואין צורך שנהפוך; המקרא. ועוד, כי הכתוב שאמר **ולא הבאיש ורמה לא היתה בו** , הוא המוכיח כן, כי אלו לא היה מרים תולעים עד אשר עלה באשו תחלה, כשאמר ולא הבאיש, כבר הבטיחנו שלא היתה בו רמה, ולמה יכפול אחרי כן ורמה לא היתה בו. אבל אם הרים תולעים תחלה כפשוטו של מקרא, הוצרך לומר שזה לא הבאיש וגם לא עלתה בו רמה כלל. ואף מן המתליעים בטבע לא יבאשו רק החמים ולחים מהם, אבל היבשים ירומו תולעים ולא יבאשו כלל כעצים המתליעים והפירות המרימים תולעים באיביהן או אחרי כן, וספר הכתוב שגם זה הבאיש בנס:
@84 **ובאלה** שמות רבה (כה י יד) אמרו וכי יש לך דבר שבתחלה עושה תולעים ואחר כך מבאיש, אלא שהקב''ה בקש להראות מעשיהם לבריות, שלא יריחו את ריחו בערב וישליכו אותו, שהיה עושה כל הלילה שורות שורות של תולעים, מיד **ויקצוף עליהם משה** :
@87 **אשר תאפו אפו** . פירש רש''י מה שאתם רוצים לאפות בתנור או לבשל במים אפו ובשלו היום לשני ימים. ואם כן יאמר את אשר תאפו משני העומר אשר בידכם אפו היום, ואת אשר תבשלו משניהם בשלו עתה, ואת כל העודף לכם משבעכם היום הניחו לכם למשמרת עד הבקר. ובבקר כאשר ראו שלא הבאיש באו לפניו כי לא רצו לאכול ממנו מיום אל יום אע''פ שהתיר להם להניחו עד הבקר. ובבקר התיר להם אכלוהו היום הזה בלבד, כי על כן אמרתי להניחו למשמרת. והודיעם בטעם המצוה כי **היום לא תמצאוהו בשדה** , כי השם יעשה כן בעבור שהוא שבת קדש לה'. ומה שאמר **ואת כל העודף** , יתכן שלא יתן להם מדה בזה, אבל יאכלו כרצונם בששי, כי העודף יספיק לשבת כי ברכת ה' היא:
@87 **ורבי** אברהם אמר את אשר תאפו כמנהגם אפו לכם היום, והוא העומר הידוע להם, ואת כל העודף שהוא העומר השני הניחו לכם למשמרת עד הבקר, ולא הגיד מה יעשו ממנו, ובבקר אמר להם אכלוהו היום. ואם כן יאכלוהו בשבת חי מבלי שיאפו או יבשלו בפרור ועשו ממנו עוגות כמנהגם. והראשון יותר נכון, וכן דעת אונקלוס:
@101 **ויסעו כל עדת בני ישראל ממדבר סין למסעיהם** :
@101 **על פי ה' ויחנו ברפידים** . יאמר שנסעו ממדבר סין שחנו שם בנסעם מאלים, והלכו למסעים רבים שעשו על פי השם, ואחרי כן חנו ברפידים. ואמר זה דרך קצרה, כי בנסעם תחלה ממדבר סין חנו בדפקה, ואחרי כן באלוש, ומאלוש לרפידים, וזה טעם ''למסעיהם'', כי היו להם מסעים ממדבר סין אל רפידים, ולא באו שם במסע הראשון, אבל לא בא עתה אלא לפרש תלונותם, כי בתחלת בואם במדבר ההוא ילונו על הלחם ועתה יריבו על המים:
@101 **ואין מים לשתות העם** . כאשר באו אל המקום ההוא ולא מצאו שם עיינות מים, מיד עשו מריבה עם משה. וזה טעם **וירב העם עם משה** , כי התלונות במקומות שנאמר בהם ''וילונו'' היא תרעומת, שהיו מתרעמים על ענינם לאמר מה נעשה, מה נאכל, ומה נשתה, אבל ''וירב'' שעשו עמו מריבה ממש, ובאו עליו לאמר תנו לנו מים אתה ואהרן אחיך, כי עליכם הדבר ודמינו עליכם. ומשה אמר להם **מה תריבון עמדי מה תנסון את ה'** , כי הריב הזה לנסות את ה' הוא היוכל תת לכם מים, כי אם תחרישו מעלי ותתפללו אליו אולי יענה אתכם וכן היה הדבר בלבם לנסות כאשר אמר (בפסוק ז), **ועל נסותם את ה' לאמר היש ה' בקרבנו אם אין** , ואז רפתה רוחם מעליו, ועמדו יום או יומים מסתפקים במים שבכליהם, ואחרי כן **ויצמא שם העם למים וילן העם על משה** , כענין התרעומות אשר המה עושים בכל לבקש דבר, שיאמרו למה זה העליתנו ממצרים. וכראות משה כי צמאו התפלל לשם והגיד לפניו צרתו במריבה שעשו עמו בראשונה. ור''א אמר כי היו שתי כתות, האחת מריבה והאחת מנסה את ה', והנכון מה שאמרתי:
@103 **להמית אותי ואת בני ואת מקני בצמא** . יזכירו לו בתלונותם גם המקנה, לאמר לו כי הם צריכים מים רבים, וצריך לתת עצה לכלם, ולכך נאמר בשנית **ויצאו מים רבים ותשת העדה ובעירם** (במדבר כ יא). ורבותינו אמרו (מכילתא כאן) השוו בהמתן לגופן, אמרו בהמה של אדם היא חייו המהלך בדרך אם אין בהמתו עמו מסתגף הוא. וטעם הזכירם אותי ואת בני, ולא אמרו סתם ''להמיתנו בצמא'' או ''להמית את כל הקהל הזה'' שיכלול אנשים ונשים וטף, כמאמרם בשאר המקומות (לעיל טז ג), כי יזכירו לו הבנים להרבות עליו תלונה שימהר לדבר, כי הקטנים לא יסבלו הצמא כלל וימותו לעיני אביהם, כטעם דבק לשון יונק אל חכו בצמא (איכה ד ד):
@105 **עבור לפני העם** . כלשון העביר אותו לערים (בראשית מז כא), והעברתי את אויביך בארץ לא ידעת (ירמיה טו יד), שתעבור מהם אל אחר, או כמו ויעבור את הכושי (ש''ב יח כג), והוא עבר לפניהם (בראשית לג ג), שקדם ללכת קודם להם. וענין הכתוב הזה, כי העם היו ברפידים, והצור אשר יצאו ממנו המים היה בחורב, והוא הר סיני, על דעת הראשונים (ראה במסכת שבת פט:), או עיר לפני ההר קרוב לו על דעתי, כאשר אפרש עוד (להלן יט א, דברים א ו). והנה הוצרך משה לקדם לפני העם לעבור מרפידים אל חורב כמהלך פרסה או פרסאות, רחוק מן המחנה לפניהם, ועל כן אמר לו **עבור לפני העם וקח אתך מזקני ישראל והלכת** , כלומר שתלך עד שתראה אותי עומד לפניך על הצור בחורב:
@105 **והנה** הכה בצור ויצאו ממנו מים, ולא ספר הכתוב ותשת העדה ובעירם כאשר בשניה (במדבר כ יא), אבל בידוע שעשו כן. וברור הוא שלא הלכו העם אל חורב לשתות, כי לא באו לפני הר סיני עד אחרי כן בחדש השלישי. אבל שלחו שם נעריהם ובהמתם לשאוב מים ולהביא להם כמנהג המחנות. וקרוב אלי שיצאו מים מן הצור בחורב, מים קרים נוזלים, הלכו אל רפידים, ושם שתו אותם, והוא שאמר הכתוב (תהלים עח טז) ויוציא נוזלים מסלע ויורד כנהרות מים, וכתוב (שם קה מא) פתח צור ויזובו מים הלכו בציות נהר. ומה שאמר (שם עח כ) הן הכה צור ויזובו מים ונחלים ישטופו, גם הוא על הצור הזה בחורב על דרך הפשט:
@105 **והסלע** השני אשר היה בקדש נבקע בו כמו באר נובע מים, ועל כן אמר (במדבר כא טז) הוא הבאר אשר אמר ה' למשה, ואמרו בשירה (שם שם יח) באר חפרוה שרים, כי היה כמו באר חפורה, ולכן אמר שם (כ יא) **ותשת העדה ובעירם** , ששתו מיד שם באותו המקום, אבל כאן היו נהרות שוטפים ממנו ושותין בבתיהם לרצונם. ואע''פ שהיה הכל בארה של מרים, כקבלת רבותינו (במדב''ר יט כה), יתכן שהיה בפעם הראשון וכל הארבעים שנה מושך מים כנהרות שוטפות, ובפעם השנית מפני העונש אשר היה שם נעשה כמו באר חפורה מלאה מים חיים:
@105 **וטעם ומטך אשר הכית בו** . בצווי לאהרן. והזכיר בו מכת היאור, ולא אמר ''והמטה אשר נהפך לנחש'', או ''והמטה אשר עשית בו את האותות'', להזכיר בו פלא, כי אז הפך המים לדם והסיר אותם מטבעם, ועתה יביא מים בצור החלמיש, והנה יעשה בו דבר והפכו:
@106 **הנני עומד לפניך שם על הצור בחורב** . בעבור כי הפלא במים במקום הזה עתה היה קבוע, שיהיה הבאר עמהם כל ימי המדבר כדברי רבותינו (במדב''ר יט כה), בעבור זה נגלית עליו השכינה במקום ההוא, כמו שאמר במן (לעיל טז ז) ובקר וראיתם את כבוד ה', בעבור היותו פלא קיים:
@109 **ויאמר משה אל יהושע** . נראה מכאן כי משה מיום היותו לפניו היה קורא אותו יהושע, וכן כתוב (להלן לב יז) וישמע יהושע את קול העם. והכתוב שאמר בענין המרגלים ויקרא משה להושע בן נון יהושע (במדבר יג טז), למבראשונה ידבר, הודיענו כי זה הושע בן נון אשר בחרו במרגלים הוא אשר קראו משה יהושע. וכדברי רבותינו (סוטה לד:) שאמר יה יושיעך מעצת מרגלים, להגיד כי בעבור זה המעשה שהיה משה יודע שהוא עתיד ללכת עם המרגלים קרא לו השם הזה. או נאמר כי אז קבע לו משה אותו השם בפני העדה שלא יקרא שמו עוד הושע ויהיה שמו יהושע:
@109 **והטעם** שצוה משה את יהושע להלחם בעמלק, בעבור שיתפלל הוא בנשיאות כפים על ראש הגבעה, ועלה שם כדי שיראה את ישראל הנלחמים וישים עינו עליהם לטובה, וגם הם יראו אותו פורש כפיו השמימה ומרבה בתפלה ויבטחו בו ויוסיפו אומץ וגבורה:
@109 **ובפרקי** ר' אליעזר (פרק מד) עוד, כל ישראל יצאו חוץ לאהליהם וראו את משה כורע על ברכיו והם כורעים על ברכיהם, נופל פניו ארצה והם נופלים על פניהם ארצה, פורש את ידיו לשמים והם פורסים את ידיהם לשמים, כשם ששליח צבור מתפלל כך כל העם עונין אחריו, והפיל הקב''ה את עמלק ואת עמו ביד יהושע (עכ''ל). ואם כן יהיה טעם ''ומטה האלהים בידי'' לומר כי כאשר עלה על ראש הגבעה וראה את עמלק נטה ידו במטה להביא עליהם מכות דבר וחרב ואבדן, כענין הנאמר ביהושע נטה בכידון אשר בידך אל העי כי בידך אתננה (יהושע ח יח), כי בעת היותו מתפלל וכפיו פרושות השמים לא יתפוש בידו דבר:
@109 **והיה** כל הענין הזה שעשה משה רבינו, מפני שהיה עמלק גוי איתן וחזק מאד, וישראל אינם מלומדי מלחמה ולא ראו אותה מעולם, כאשר אמר פן ינחם העם בראותם מלחמה (לעיל יג יז), והוא עיף ויגע ככתוב במשנה תורה (דברים כה יח), על כן פחד מהם והוצרך לכל התפלה והתחנה הזאת:
@109 **ויתכן** שפחד משה פן יתגבר בחרבו מפני היותו עם נוחל החרב מברכת הזקן שאמר לו ועל חרבך תחיה (בראשית כז מ), כי המלחמה מן המשפחה הזאת היא הראשונה והאחרונה לישראל, כי עמלק מזרע עשו (שם לו יב), וממנו באה אלינו המלחמה בראשית הגוים, ומזרעו של עשו היה לנו הגלות והחרבן האחרון, כאשר יאמרו רבותינו (ע''ז ב:) שאנחנו היום בגלות אדום, וכאשר ינוצח הוא, ויחלש הוא ועמים רבים אשר אתו, ממנה נושע לעולם, כאשר אמר (עובדיה א כא) ועלו מושיעים בהר ציון לשפוט את הר עשו והיתה לה' המלוכה. והנה כל אשר עשו משה ויהושע עמהם בראשונה יעשו אליהו ומשיח בן יוסף עם זרעם, על כן התאמץ משה בדבר:
@111 **וכאשר יניח ידו** . על דרך הפשט, כאשר הניח ידו באונס מפני כובד ידיו ראה שגבר עמלק, וצוה לאהרן וחור שיתמכו בהם ולא יניחם עוד. ורבותינו אמרו במדרש (ספר הבהיר אות קלח) וכי משה היה עושה שיגבר עמלק עליו, אלא אסור לאדם לשהות שלש שעות כפיו פרושות השמים:
@112 וטעם **ויהי ידיו אמונה** . שהיו עומדות וקיימות ברוממותן, כלשון ואמנה על המשוררים דבר יום ביומו (נחמיה יא כג), וכן אנחנו כורתים אמנה (שם י יא), דבר קיים בברית, וכן היתד התקועה במקום נאמן (ישעיה כב כג), חזק:
@112 **ועל** דרך האמת, נשא עשר אצבעות לרום השמים לרמוז על עשר ספירות לדבקה באמונה הנלחם לישראל, ובכאן נתבאר ענין נשיאות כפים בברכת כהנים וסודו:
@114 **כתוב זאת זכרון בספר** . אמר רבי אברהם כי הוא ספר נודע, והוא ''ספר מלחמות ה''' (במדבר כא יד), וכתוב בו המלחמות שעשה השם בעבור יראיו, ויתכן שהיה מימות אברהם. ואין בדבריו אלה רק תואנה. והנכון בעיני, כי ''בספר'' ירמוז לספר התורה, כענין שכתוב (דברים לא כו) לקוח את ספר התורה הזה, יאמר כתוב זאת בספר תורתי שיזכרו בני ישראל מה שעשה עמלק, כי מחה אמחה את זכרו ונתתי נקמתי בו ביד עמי ישראל. וזו היא המצוה שכתוב לנו במשנה תורה (דברים כה יז) זכור את אשר עשה לך עמלק. **ואמר** ושים באזני יהושע, לצוותו להזכיר לישראל את כל התלאה אשר באה להם על ידו, כי הוא היודע ועד, וירמוז כי אחרי שיירשו הארץ ימחו אותו, כי מצוה עליהם תחלה להכרית שבעת הגוים וינחלו הארץ, זהו שנאמר שם (כה יט) והיה בהניח ה' אלהיך לך וגו', ואם היה בימי יהושע בן נון כן, היה מזהירם למחות אותו, אבל נשאר הארץ לרשתה בימיו הרבה מאד (יהושע יג א), ולא הגיע זמנה עד מלוך שאול:
@116 **כי יד על כס יה** . ידו של הקב''ה הורמה לישבע בכסאו להיות לו מלחמה ואיבה בעמלק עולמית. ומהו כס ולא נאמר כסא, ואף השם נחלק לחציו, נשבע הקב''ה שאין הכסא שלם ואין השם מלא עד שימח שמו של עמלק בן עשו, ומשנמחה שמו יהי שם ה' מלא והכסא שלם, שנאמר (תהלים ט ז) האויב תמו חרבות לנצח, זהו עשו, שנאמר ועברתו שמרה נצח (עמוס א יא), אבד זכרם המה (תהלים ט ז), מה כתיב אחריו וה' לעולם ישב (שם ח), הרי השם מלא, כונן למשפט כסאו (שם), הרי כסא שלם. לשון רש''י. ומדרש חכמים הוא (תנחומא תצא יא):
@116 **ויש** מפרשים כי כאשר תהיה יד על כסא ה' תהיה מלחמה לה' בעמלק, וכן תהיה מדור לדור. והענין, כי כאשר יהיה מלך בישראל יושב על כסא ה' ילחם בעמלק, והוא רמז לשאול המלך הראשון, וכן מדר דר, לאמר כי כל מלך בישראל חייב להלחם בהם עד שימחו. וגם זה מדרש הגמרא שאמרו (סנהדרין כ:) כשהוא אומר כי **יד על כס יה מלחמה לה' בעמלק מדר דר** , הרי להעמיד עליהם מלך תחלה, ואין כס יה אלא מלך, שנאמר (דהי''א כט כג) וישב שלמה, כדאיתא בפרק כהן גדול (סנהדרין כ:). ועל דרך הפשט נכון הוא:
@116 **ועל** דרך האמת, כי **היד** אשר **על כסא יה** , והיא **מלחמה לה'** , הויה **בעמלק מדר דר** , כי מדת הדין של מעלה תהיה בו למחותו לעולם מדור דור. ומדרש חכמים (תנחומא תצא טו) בשם המלא ובכסא השלם ירמוז לזה:
@116 **וטעם** העונש שנענש עמלק יותר מכל העמים, בעבור כי כל העמים שמעו וירגזון (לעיל טו יד), ופלשת אדום ומואב ויושבי כנען נמוגו (שם) מפני פחד ה' ומהדר גאונו, ועמלק בא ממרחק כמתגבר על השם, ולכך אמר בו ולא ירא אלהים (דברים כה יח), ועוד כי הוא נין עשו וקרוב לנו, עובר מתעבר על ריב לא לו:
